arguments.content:
"""Flask application factory for the multi-mode calculator web app.

Route map
---------
/                 Scientific calculator (default mode)
/graph            Graphing calculator
/date             Date calculator
/api/calculate    JSON API for scientific expression evaluation
/api/graph        JSON API for function sampling / plotting data
/api/date         JSON API for date arithmetic

The page routes render templates from ``templates/``.  While the UI is still
being built out (or if a template is missing), a tiny inline placeholder page is
served so that the app always stays importable *and* runnable.  As soon as the
real templates land they are picked up automatically -- no code change needed.

The JSON APIs delegate to the ``calculators`` package.  Those helpers are
implemented in follow-up work; until then the endpoints answer with a clear
``501`` payload instead of crashing.

Run locally::

    pip install -r requirements.txt
    flask --app app run --debug
"""

from __future__ import annotations

import importlib
from typing import Any, Callable

from flask import Flask, jsonify, render_template, request
from jinja2 import TemplateNotFound

__all__ = ["create_app", "MODES"]

#: Single source of truth for the calculator modes used by templates/JS.
MODES = {
    "scientific": {
        "id": "scientific",
        "label": "Scientific",
        "route": "/",
        "endpoint": "scientific",
        "template": "scientific.html",
        "api": "/api/calculate",
    },
    "graph": {
        "id": "graph",
        "label": "Graphing",
        "route": "/graph",
        "endpoint": "graph",
        "template": "graph.html",
        "api": "/api/graph",
    },
    "date": {
        "id": "date",
        "label": "Date",
        "route": "/date",
        "endpoint": "date",
        "template": "date.html",
        "api": "/api/date",
    },
}

DEFAULT_MODE = "scientific"

_STUB_PAGE = """<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{label} calculator &middot; placeholder</title>
  <style>
    body {{ margin: 0; min-height: 100vh; display: grid; place-items: center;
            font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
            background: #0b1020; color: #e6ebff; }}
    main {{ max-width: 34rem; padding: 2.5rem; border: 1px solid #2a3357;
            border-radius: 1rem; background: #111730; }}
    h1 {{ margin: 0 0 .5rem; font-size: 1.35rem; letter-spacing: .01em; }}
    p {{ margin: .35rem 0; color: #9aa6d0; line-height: 1.55; }}
    code {{ background: #0b1020; border-radius: .35rem; padding: .1rem .35rem;
            color: #8ee6c7; }}
    nav a {{ color: #9ad2ff; margin-right: .9rem; text-decoration: none; }}
    nav a:hover {{ text-decoration: underline; }}
  </style>
</head>
<body>
  <main>
    <p><code>{mode}</code> mode &rarr; template <code>{template}</code></p>
    <h1>{label} calculator</h1>
    <p>This is a scaffold placeholder. The real {label} interface will be
       rendered here from <code>templates/{template}</code>.</p>
    <p>API endpoint: <code>{api}</code></p>
    <nav>{nav}</nav>
  </main>
</body>
</html>
"""


def _render_mode(mode: str):
    """Render the template for *mode*, falling back to an inline placeholder."""
    spec = MODES[mode]
    context = {
        "mode": mode,
        "mode_spec": spec,
        "modes": MODES,
        "active_mode": mode,
    }
    try:
        return render_template(spec["template"], **context)
    except TemplateNotFound:
        nav = " ".join(
            '<a href="{route}">{label}</a>'.format(**m)
            for m in MODES.values()
            if m["id"] != mode
        )
        return _STUB_PAGE.format(
            mode=mode,
            label=spec["label"],
            template=spec["template"],
            api=spec["api"],
            nav=nav,
        )


# --------------------------------------------------------------------------- #
# API helpers
# --------------------------------------------------------------------------- #
def _resolve(path: str) -> Callable[..., Any] | None:
    """Return a callable from ``calculators`` if it exists, else ``None``.

    ``path`` is a dotted ``module:attribute`` reference, e.g.
    ``calculators.scientific:evaluate``.  Missing modules/attributes are not an
    error at this stage of the build -- the endpoint reports ``501`` instead.
    """
    module_name, _, attr = path.partition(":")
    try:
        module = importlib.import_module(module_name)
    except ImportError:
        return None
    candidate = getattr(module, attr, None)
    return candidate if callable(candidate) else None


def _json_body() -> dict[str, Any]:
    """Best-effort JSON body parsing (also tolerates empty bodies)."""
    return request.get_json(silent=True) or {}


def _not_implemented(feature: str):
    return (
        jsonify(
            ok=False,
            error="not_implemented",
            feature=feature,
            message=f"The {feature} backend is not wired up yet.",
        ),
        501,
    )


def _bad_request(message: str):
    return jsonify(ok=False, error="bad_request", message=message), 400


def create_app(config: dict[str, Any] | None = None) -> Flask:
    """Application factory used by ``flask --app app run`` and by tests."""
    app = Flask(__name__)
    app.config.update(
        SECRET_KEY="dev-secret-change-me",
        JSON_SORT_KEYS=False,
    )
    if config:
        app.config.update(config)

    app.extensions["calculator_modes"] = MODES

    @app.context_processor
    def inject_modes() -> dict[str, Any]:
        return {"modes": MODES, "default_mode": DEFAULT_MODE}

    # ----------------------------- page routes ----------------------------- #
    @app.get("/")
    def scientific():
        return _render_mode("scientific")

    @app.get("/graph")
    def graph():
        return _render_mode("graph")

    @app.get("/date")
    def date():
        return _render_mode("date")

    # ------------------------------ JSON APIs ------------------------------ #
    @app.post("/api/calculate")
    def api_calculate():
        payload = _json_body()
        expression = payload.get("expression")
        if not isinstance(expression, str) or not expression.strip():
            return _bad_request("Expected a non-empty 'expression' string.")
        evaluate = _resolve("calculators.scientific:evaluate")
        if evaluate is None:
            return _not_implemented("scientific")
        result = evaluate(expression, angle_mode=payload.get("angle_mode", "deg"))
        return jsonify(ok=True, result=result)

    @app.post("/api/graph")
    def api_graph():
        payload = _json_body()
        expression = payload.get("expression")
        if not isinstance(expression, str) or not expression.strip():
            return _bad_request("Expected a non-empty 'expression' string.")
        sample = _resolve("calculators.graphing:sample")
        if sample is None:
            return _not_implemented("graphing")
        series = sample(
            expression,
            x_min=payload.get("x_min", -10),
            x_max=payload.get("x_max", 10),
            x_range=payload.get("range"),
            samples=payload.get("samples", 400),
            angle_mode=payload.get("angle_mode", "deg"),
        )
        return jsonify(ok=True, series=series)

    @app.post("/api/date")
    def api_date():
        payload = _json_body()
        operation = payload.get("operation") or payload.get("op")
        if not isinstance(operation, str) or not operation.strip():
            return _bad_request("Expected an 'operation' string.")
        calculate = _resolve("calculators.dates:calculate")
        if calculate is None:
            return _not_implemented("date")
        return jsonify(ok=True, result=calculate(operation=operation, **{
            k: v for k, v in payload.items() if k not in {"operation", "op"}
        }))

    # --------------------------- error handlers --------------------------- #
    @app.errorhandler(404)
    def not_found(error):
        if request.path.startswith("/api/"):
            return jsonify(ok=False, error="not_found"), 404
        return '<h1>404</h1><p>Page not found. <a href="/">Back to calculator</a></p>', 404

    @app.errorhandler(405)
    def method_not_allowed(error):
        if request.path.startswith("/api/"):
            return jsonify(ok=False, error="method_not_allowed"), 405
        return error

    return app


#: Module-level app so ``flask --app app run`` works without a factory flag.
app = create_app()


if __name__ == "__main__":
    app.run(debug=True)

