" ; rm -f templates/scientific.html; ls templates

arguments.content:
"""Safe scientific expression engine for the calculator app.

The engine is deliberately dependency-free (``ast`` + ``math`` + ``decimal`` from
the standard library) and *safe*: user input is parsed with
:func:`ast.parse` and then walked against an explicit **allow-list** of node
types.  ``eval()``, ``exec()`` and ``compile()`` are never used, so attribute
access, indexing, comprehensions, lambdas, dunder tricks, imports and string
values can never reach the interpreter.

Public API
----------
``calculate(expression, degrees=True)``
    The single contract shared by the Flask JSON API and the browser JS::

        {
            "ok": bool,
            "value": number | None,   # 42, 0.5 ... (None when ok is False)
            "formatted": str,         # display string, "" when ok is False
            "tokens": [ ... ],        # token dicts for the on-screen token strip
            "error": str | None,      # friendly message when ok is False
        }

``evaluate(expression, degrees=True, variables=None)``
    Return the raw number, raising :class:`CalculationError` on bad input.
    The optional ``variables`` mapping is used by the graphing sampler to bind
    ``x`` (and friends); it is not exposed through ``calculate``.

``tokenize(expression)``
    Return ``[{"type", "text", "value", "start"}, ...]`` for UI display.  Token
    ``type`` is one of ``number``, ``name``, ``operator``, ``lparen``,
    ``rparen``, ``comma`` or ``error``.

``normalise(expression)`` (alias ``normalize``)
    Map display symbols to their ASCII equivalents: ``× · ⋅`` -> ``*``,
    ``÷ ∕`` -> ``/``, ``− – —`` -> ``-``, ``√`` -> ``sqrt``, ``π`` -> ``pi``,
    ``τ`` -> ``tau``, ``²`` -> ``**2``, ``³`` -> ``**3``, ``^`` -> ``**`` plus
    full-width parentheses/commas.

``format_number(value)`` (alias ``format_result``)
    Render a number with up to 12 significant digits, stripping float noise
    (``0.1 + 0.2`` -> ``"0.3"``) and falling back to scientific notation for
    very large/small magnitudes.

Angle mode
----------
``degrees=True`` affects **only** the trigonometry: ``sin``/``cos``/``tan``
(and the hyperbolics' degree-free counterparts are unaffected) take degrees as
input, and ``asin``/``acos``/``atan`` return degrees.  Everything else is
unit-free.
"""

from __future__ import annotations

import ast
import math
import re
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_EVEN, localcontext
from typing import Any, Callable, Iterable, Mapping, Sequence

__all__ = [
    "CalculationError",
    "CONSTANTS",
    "FUNCTIONS",
    "SIGNIFICANT_DIGITS",
    "calculate",
    "evaluate",
    "format_number",
    "format_result",
    "normalise",
    "normalize",
    "tokenize",
]

#: Number of significant digits used by :func:`format_number`.
SIGNIFICANT_DIGITS = 12

#: Hard limit on expression length -- keeps pathological input cheap to reject.
MAX_EXPRESSION_LENGTH = 512

#: Hard limit on the number of AST nodes in one expression.
MAX_NODES = 400

#: ``factorial(n)`` refuses absurd inputs instead of allocating huge integers.
MAX_FACTORIAL = 1000

#: Largest integer exponent we are willing to evaluate (``2 ** 10**9`` is not).
MAX_INT_EXPONENT = 10_000


class CalculationError(ValueError):
    """Raised for any user-correctable problem (bad syntax, domain error...).

    ``str(exc)`` is always a short, friendly, end-user facing message.
    """


# --------------------------------------------------------------------------- #
# Display-symbol normalisation
# --------------------------------------------------------------------------- #
_CHAR_MAP = {
    # multiplication
    "\u00d7": "*",  # ×
    "\u00b7": "*",  # ·
    "\u22c5": "*",  # ⋅
    "\u2219": "*",  # ∙
    "\u2217": "*",  # ∗
    # division
    "\u00f7": "/",  # ÷
    "\u2215": "/",  # ∕
    "\u2044": "/",  # ⁄
    # minus / dashes
    "\u2212": "-",  # −
    "\u2013": "-",  # –
    "\u2014": "-",  # —
    "\u2010": "-",  # ‐
    # powers
    "\u005e": "**",  # ^  (unit-aware caret maps to Python power)
    "\u00b2": "**2",  # ²
    "\u00b3": "**3",  # ³
    # roots / constants
    "\u221a": "sqrt",  # √  (write sqrt(9), i.e. √(9))
    "\u03c0": "pi",  # π
    "\u03c4": "tau",  # τ
    # unicode punctuation
    "\uff08": "(",
    "\uff09": ")",
    "\uff0c": ",",
    "\u3002": ".",
    "\u0000": " ",
}

_TRANSLATION = str.maketrans(_CHAR_MAP)


def normalise(expression: str) -> str:
    """Translate display symbols (``× ÷ − √ π``) into parseable ASCII.

    Trailing ``=`` (users habitually type it) and surrounding whitespace are
    dropped.  Newlines/tabs become spaces so pasted text still parses.
    """
    if not isinstance(expression, str):
        raise CalculationError("Expression must be text")
    text = expression.translate(_TRANSLATION)
    text = text.replace("\r", " ").replace("\n", " ").replace("\t", " ")
    text = text.strip()
    while text.endswith("="):
        text = text[:-1].rstrip()
    return text


#: American spelling alias.
normalize = normalise


# --------------------------------------------------------------------------- #
# Tokenizer (for the UI token strip)
# --------------------------------------------------------------------------- #
_NUMBER_RE = r"(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?"
_TOKEN_RE = re.compile(
    r"""
      (?P<number>NUM)
    | (?P<name>[A-Za-z_][A-Za-z_0-9]*)
    | (?P<operator>\*\*|//|<<|>>|[-+*/%^<>!&|~@])
    | (?P<lparen>\()
    | (?P<rparen>\))
    | (?P<comma>,)
    | (?P<dot>\.)
    | (?P<space>\s+)
    """.replace("NUM", _NUMBER_RE),
    re.VERBOSE,
)

_TOKEN_TYPE_BY_GROUP = {
    "operator": "operator",
    "lparen": "lparen",
    "rparen": "rparen",
    "comma": "comma",
}


def _tokenise(source: str) -> tuple[list[dict[str, Any]], str | None]:
    """Tokenise *source*; return ``(tokens, error_message_or_None)``.

    Tokenising never raises: an unexpected character becomes a token of type
    ``error`` and the matching friendly message is returned alongside.
    """
    tokens: list[dict[str, Any]] = []
    error: str | None = None
    position = 0
    while position < len(source):
        match = _TOKEN_RE.match(source, position)
        if match is None:
            char = source[position]
            tokens.append({"type": "error", "text": char, "value": None, "start": position})
            if error is None:
                error = f"Unexpected character {char!r} at position {position + 1}"
            position += 1
            continue
        kind = match.lastgroup or ""
        text = match.group()
        start = position
        position = match.end()
        if kind == "space":
            continue
        if kind == "number":
            tokens.append({"type": "number", "text": text, "value": float(text), "start": start})
        elif kind == "name":
            tokens.append({"type": "name", "text": text, "value": None, "start": start})
        elif kind == "dot":
            tokens.append({"type": "error", "text": text, "value": None, "start": start})
            if error is None:
                error = f"Unexpected character '.' at position {start + 1}"
        else:
            tokens.append(
                {
                    "type": _TOKEN_TYPE_BY_GROUP[kind],
                    "text": text,
                    "value": None,
                    "start": start,
                }
            )
    return tokens, error


def tokenize(expression: str) -> list[dict[str, Any]]:
    """Return the display token list for *expression* (see module docstring).

    Unparseable characters appear as ``{"type": "error", ...}`` tokens so the UI
    can highlight them; the function itself never raises.
    """
    try:
        source = normalise(expression)
    except CalculationError:
        return []
    tokens, _ = _tokenise(source)
    return tokens


# --------------------------------------------------------------------------- #
# Number formatting
# --------------------------------------------------------------------------- #
def _format_scientific(value: Decimal) -> str:
    mantissa, _, exponent = format(value, "e").partition("e")
    mantissa = mantissa.rstrip("0").rstrip(".")
    if mantissa in ("", "-", "-0"):
        mantissa = "0"
    return f"{mantissa}e{int(exponent)}"


def format_number(value: Any, *, significant_digits: int = SIGNIFICANT_DIGITS) -> str:
    """Format *value* for display with up to *significant_digits* digits.

    Float noise disappears because the value is rounded to 12 significant
    digits before printing (``0.30000000000000004`` -> ``"0.3"``).  Magnitudes
    outside ``1e-9 <= |x| < 1e12`` use compact scientific notation
    (``"1.26765060023e+30"``).
    """
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise CalculationError("Result is not a number")
    if isinstance(value, int):
        if abs(value) < 10 ** 12:
            return str(value)
        rounded = _round_significant(Decimal(value), significant_digits)
        return _format_scientific(rounded)
    number = float(value)
    if not math.isfinite(number):
        raise CalculationError("Result is not a finite number")
    if number == 0:
        return "0"
    rounded = _round_significant(Decimal(number), significant_digits)
    if rounded.is_zero():
        return "0"
    if -9 <= rounded.adjusted() < SIGNIFICANT_DIGITS:
        text = format(rounded, "f")
        if "." in text:
            text = text.rstrip("0").rstrip(".")
        return "0" if text in ("", "-", "-0") else text
    return _format_scientific(rounded)


def _round_significant(value: Decimal, digits: int) -> Decimal:
    with localcontext() as ctx:
        ctx.prec = max(1, int(digits))
        ctx.rounding = ROUND_HALF_EVEN
        return +value


#: Alias used by some call sites / mirrored JS helpers.
format_result = format_number


# --------------------------------------------------------------------------- #
# Function library
# --------------------------------------------------------------------------- #
@dataclass(frozen=True)
class Function:
    """A whitelisted calculator function."""

    name: str
    min_args: int
    max_args: int
    fn: Callable[[Sequence[float], bool], Any]
    description: str = ""


def _check_number(value: Any, what: str = "value") -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise CalculationError(f"{what.capitalize()} must be a number")
    return float(value)


def _to_radians(angle: float, degrees: bool) -> float:
    return math.radians(angle) if degrees else angle


def _from_radians(angle: float, degrees: bool) -> float:
    return math.degrees(angle) if degrees else angle


def _deg_step(angle: float, step: float) -> int | None:
    """Return ``angle / step`` as an int when *angle* is an exact multiple."""
    if not math.isfinite(angle):
        return None
    ratio = angle / step
    rounded = round(ratio)
    if abs(ratio - rounded) < 1e-12:
        return int(rounded % 4) if step == 90.0 else int(rounded)
    return None


def _sin(args: Sequence[float], degrees: bool) -> float:
    angle = _check_number(args[0], "angle")
    if degrees:
        step = _deg_step(angle, 90.0)
        if step is not None:
            return (0.0, 1.0, 0.0, -1.0)[step]
    return math.sin(_to_radians(angle, degrees))


def _cos(args: Sequence[float], degrees: bool) -> float:
    angle = _check_number(args[0], "angle")
    if degrees:
        step = _deg_step(angle, 90.0)
        if step is not None:
            return (1.0, 0.0, -1.0, 0.0)[step]
    return math.cos(_to_radians(angle, degrees))


def _tan(args: Sequence[float], degrees: bool) -> float:
    angle = _check_number(args[0], "angle")
    if degrees:
        step = _deg_step(angle, 90.0)
        if step is not None:
            if step % 2:
                raise CalculationError("Tangent is undefined at 90\u00b0 + 180\u00b0\u00b7k")
            return 0.0
    radians = _to_radians(angle, degrees)
    if abs(math.cos(radians)) < 1e-15:
        raise CalculationError("Tangent is undefined here")
    return math.tan(radians)


def _asin(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if value < -1.0 or value > 1.0:
        raise CalculationError("asin expects a value between -1 and 1")
    return _from_radians(math.asin(value), degrees)


def _acos(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if value < -1.0 or value > 1.0:
        raise CalculationError("acos expects a value between -1 and 1")
    return _from_radians(math.acos(value), degrees)


def _atan(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    return _from_radians(math.atan(value), degrees)


def _sinh(args: Sequence[float], degrees: bool) -> float:
    return math.sinh(_check_number(args[0]))


def _cosh(args: Sequence[float], degrees: bool) -> float:
    return math.cosh(_check_number(args[0]))


def _tanh(args: Sequence[float], degrees: bool) -> float:
    return math.tanh(_check_number(args[0]))


def _asinh(args: Sequence[float], degrees: bool) -> float:
    return math.asinh(_check_number(args[0]))


def _acosh(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if value < 1:
        raise CalculationError("acosh expects a value of at least 1")
    return math.acosh(value)


def _atanh(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if value <= -1 or value >= 1:
        raise CalculationError("atanh expects a value between -1 and 1")
    return math.atanh(value)


def _log(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    base = _check_number(args[1]) if len(args) == 2 else 10.0
    if value <= 0:
        raise CalculationError("Logarithm needs a positive number")
    if base <= 0 or base == 1:
        raise CalculationError("Logarithm base must be positive and not 1")
    return math.log(value, base)


def _ln(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if value <= 0:
        raise CalculationError("Logarithm needs a positive number")
    return math.log(value)


def _log2(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if value <= 0:
        raise CalculationError("Logarithm needs a positive number")
    return math.log2(value)


def _log10(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if value <= 0:
        raise CalculationError("Logarithm needs a positive number")
    return math.log10(value)


def _exp(args: Sequence[float], degrees: bool) -> float:
    return math.exp(_check_number(args[0]))


def _sqrt(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if value < 0:
        raise CalculationError("Cannot take the square root of a negative number")
    return math.sqrt(value)


def _cbrt(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    return math.copysign(abs(value) ** (1.0 / 3.0), value)


def _abs(args: Sequence[float], degrees: bool) -> float:
    return abs(_check_number(args[0]))


def _floor(args: Sequence[float], degrees: bool) -> int:
    return math.floor(_check_number(args[0]))


def _ceil(args: Sequence[float], degrees: bool) -> int:
    return math.ceil(_check_number(args[0]))


def _round(args: Sequence[float], degrees: bool) -> float:
    value = _check_number(args[0])
    if len(args) == 1:
        return float(round(value))
    digits = _check_number(args[1], "digit count")
    if digits != int(digits):
        raise CalculationError("round needs a whole number of digits")
    if abs(digits) > 15:
        raise CalculationError("round supports at most 15 digits")
    return round(value, int(digits))


def _factorial(args: Sequence[float], degrees: bool) -> int:
    value = _check_number(args[0])
    if value < 0:
        raise CalculationError("Factorial of a negative number")
    if value != int(value):
        raise CalculationError("Factorial needs a whole number")
    number = int(value)
    if number > MAX_FACTORIAL:
        raise CalculationError(f"Factorial input is too large (max {MAX_FACTORIAL})")
    return math.factorial(number)


def _comb(args: Sequence[float], degrees: bool) -> int:
    total = _check_number(args[0], "n")
    chosen = _check_number(args[1], "r")
    for label, item in (("n", total), ("r", chosen)):
        if item < 0 or item != int(item):
            raise CalculationError(f"{label} must be a whole number of at least 0")
    if chosen > total:
        raise CalculationError("r cannot be larger than n")
    return math.comb(int(total), int(chosen))


def _perm(args: Sequence[float], degrees: bool) -> int:
    total = _check_number(args[0], "n")
    chosen = _check_number(args[1], "r")
    for label, item in (("n", total), ("r", chosen)):
        if item < 0 or item != int(item):
            raise CalculationError(f"{label} must be a whole number of at least 0")
    if chosen > total:
        raise CalculationError("r cannot be larger than n")
    return math.perm(int(total), int(chosen))


#: Registry of whitelisted functions (name -> :class:`Function`).
FUNCTIONS: dict[str, Function] = {
    fn.name: fn
    for fn in (
        Function("sin", 1, 1, _sin, "Sine (degrees when degrees mode is on)"),
        Function("cos", 1, 1, _cos, "Cosine (degrees when degrees mode is on)"),
        Function("tan", 1, 1, _tan, "Tangent (degrees when degrees mode is on)"),
        Function("asin", 1, 1, _asin, "Inverse sine (result in degrees in degrees mode)"),
        Function("acos", 1, 1, _acos, "Inverse cosine (result in degrees in degrees mode)"),
        Function("atan", 1, 1, _atan, "Inverse tangent (result in degrees in degrees mode)"),
        Function("sinh", 1, 1, _sinh, "Hyperbolic sine"),
        Function("cosh", 1, 1, _cosh, "Hyperbolic cosine"),
        Function("tanh", 1, 1, _tanh, "Hyperbolic tangent"),
        Function("asinh", 1, 1, _asinh, "Inverse hyperbolic sine"),
        Function("acosh", 1, 1, _acosh, "Inverse hyperbolic cosine"),
        Function("atanh", 1, 1, _atanh, "Inverse hyperbolic tangent"),
        Function("log", 1, 2, _log, "Log base 10, or log(value, base)"),
        Function("ln", 1, 1, _ln, "Natural logarithm"),
        Function("log2", 1, 1, _log2, "Logarithm base 2"),
        Function("log10", 1, 1, _log10, "Logarithm base 10"),
        Function("exp", 1, 1, _exp, "e raised to a power"),
        Function("sqrt", 1, 1, _sqrt, "Square root"),
        Function("cbrt", 1, 1, _cbrt, "Cube root"),
        Function("abs", 1, 1, _abs, "Absolute value"),
        Function("floor", 1, 1, _floor, "Round down"),
        Function("ceil", 1, 1, _ceil, "Round up"),
        Function("round", 1, 2, _round, "Round to nearest, optional digit count"),
        Function("factorial", 1, 1, _factorial, "Factorial"),
        Function("nCr", 2, 2, _comb, "Combinations"),
        Function("nPr", 2, 2, _perm, "Permutations"),
    )
}

#: Case-insensitive lookup used by the evaluator (``Sin`` == ``sin``).
_FUNCTION_LOOKUP = {name.lower(): fn for name, fn in FUNCTIONS.items()}

#: Named constants.
CONSTANTS: dict[str, float] = {
    "pi": math.pi,
    "e": math.e,
    "tau": math.tau,
}

_CONSTANT_LOOKUP = {name.lower(): value for name, value in CONSTANTS.items()}


# --------------------------------------------------------------------------- #
# Safety: AST allow-list
# --------------------------------------------------------------------------- #
_ALLOWED_NODES: tuple[type[ast.AST], ...] = (
    ast.Expression,
    ast.BinOp,
    ast.UnaryOp,
    ast.Call,
    ast.Name,
    ast.Constant,
    ast.Load,
    # binary operators
    ast.Add,
    ast.Sub,
    ast.Mult,
    ast.Div,
    ast.FloorDiv,
    ast.Mod,
    ast.Pow,
    # unary operators
    ast.UAdd,
    ast.USub,
)

#: Nodes that users (or attackers) are likely to try; each gets a clear message.
_REJECTED_NODES: dict[type[ast.AST], str] = {
    ast.Attribute: "Attribute access is not allowed",
    ast.Subscript: "Indexing is not allowed",
    ast.Slice: "Slicing is not allowed",
    ast.Lambda: "Lambda expressions are not allowed",
    ast.ListComp: "Comprehensions are not allowed",
    ast.SetComp: "Comprehensions are not allowed",
    ast.DictComp: "Comprehensions are not allowed",
    ast.GeneratorExp: "Comprehensions are not allowed",
    ast.List: "Lists are not allowed",
    ast.Tuple: "Tuples are not allowed",
    ast.Dict: "Dictionaries are not allowed",
    ast.Set: "Sets are not allowed",
    ast.Starred: "Star arguments are not allowed",
    ast.Compare: "Comparisons are not allowed",
    ast.BoolOp: "Boolean operators are not allowed",
    ast.IfExp: "Conditional expressions are not allowed",
    ast.NamedExpr: "Assignment expressions are not allowed",
    ast.JoinedStr: "Text values are not allowed",
    ast.FormattedValue: "Text values are not allowed",
    ast.Await: "Unsupported syntax",
    ast.Yield: "Unsupported syntax",
    ast.YieldFrom: "Unsupported syntax",
    ast.Import: "Imports are not allowed",
    ast.ImportFrom: "Imports are not allowed",
    ast.Mult: "",
}


def _syntax_message(exc: SyntaxError) -> str:
    """Turn a :class:`SyntaxError` into a short, friendly message."""
    raw = (exc.msg or "").lower()
    offset = exc.offset or 0
    position = f" at position {offset}" if offset else ""
    if "never closed" in raw or "unmatched" in raw or "closing parenthesis" in raw:
        return "Mismatched parentheses"
    if "invalid decimal literal" in raw:
        return f"Malformed number{position}"
    if "invalid character" in raw:
        return f"Unexpected character{position}"
    if "leading zeros" in raw:
        return f"Malformed number{position}"
    if "too deeply nested" in raw or "too many nested" in raw:
        return "Expression is too deeply nested"
    if "invalid syntax" in raw or "unexpected" in raw or "expected" in raw:
        return f"Unexpected or incomplete input{position}"
    return f"Invalid expression{position}"


class _Validator(ast.NodeVisitor):
    """Check the tree against the allow-list before any evaluation happens."""

    def __init__(self, variables: Mapping[str, Any] | None = None) -> None:
        self.variables = variables or {}
        self.node_count = 0

    def generic_visit(self, node: ast.AST) -> None:  # noqa: D102 - see class doc
        self.node_count += 1
        if self.node_count > MAX_NODES:
            raise CalculationError("Expression is too complex")
        for rejected, message in _REJECTED_NODES.items():
            if isinstance(node, rejected):
                raise CalculationError(message)
        if not isinstance(node, _ALLOWED_NODES):
            name = type(node).__name__
            raise CalculationError(f"Unsupported syntax: {name}")
        super().generic_visit(node)

    def visit_Name(self, node: ast.Name) -> None:  # noqa: N802 - ast API
        identifier = node.id
        if identifier.startswith("__") or identifier.endswith("__"):
            raise CalculationError("Reserved names are not allowed")
        lowered = identifier.lower()
        if (
            lowered not in _CONSTANT_LOOKUP
            and lowered not in _FUNCTION_LOOKUP
            and identifier not in self.variables
        ):
            raise CalculationError(f"Unknown name '{identifier}'")
        self.generic_visit(node)

    def visit_Constant(self, node: ast.Constant) -> None:  # noqa: N802 - ast API
        value = node.value
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            if isinstance(value, complex):
                raise CalculationError("Complex numbers are not supported")
            if isinstance(value, str):
                raise CalculationError("Text values are not allowed")
            raise CalculationError("Unsupported literal")
        self.generic_visit(node)

    def visit_Call(self, node: ast.Call) -> None:  # noqa: N802 - ast API
        if not isinstance(node.func, ast.Name):
            raise CalculationError("Only plain function calls are allowed")
        name = node.func.id
        spec = _FUNCTION_LOOKUP.get(name.lower())
        if spec is None:
            raise CalculationError(f"Unknown function '{name}'")
        if node.keywords:
            raise CalculationError("Keyword arguments are not allowed")
        argc = len(node.args)
        if argc < spec.min_args or argc > spec.max_args:
            expected = (
                str(spec.min_args)
                if spec.min_args == spec.max_args
                else f"{spec.min_args}-{spec.max_args}"
            )
            raise CalculationError(
                f"{spec.name}() takes {expected} argument(s), got {argc}"
            )
        self.generic_visit(node)


def _parse(source: str) -> ast.Expression:
    """Parse *source* into an AST, mapping syntax errors to friendly messages."""
    if not source:
        raise CalculationError("Enter an expression to calculate")
    if len(source) > MAX_EXPRESSION_LENGTH:
        raise CalculationError(
            f"Expression is too long (max {MAX_EXPRESSION_LENGTH} characters)"
        )
    try:
        tree = ast.parse(source, mode="eval")
    except SyntaxError as exc:  # pragma: no cover - message mapping is tested
        raise CalculationError(_syntax_message(exc)) from None
    except (ValueError, MemoryError) as exc:  # e.g. null bytes or absurd nesting
        raise CalculationError(f"Invalid expression: {exc}") from None
    return tree


# --------------------------------------------------------------------------- #
# Evaluation
# --------------------------------------------------------------------------- #
def _eval_node(node: ast.AST, degrees: bool, variables: Mapping[str, Any]) -> Any:
    if isinstance(node, ast.Expression):
        return _eval_node(node.body, degrees, variables)
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Name):
        lowered = node.id.lower()
        if node.id in variables:
            return variables[node.id]
        if lowered in _CONSTANT_LOOKUP:
            return _CONSTANT_LOOKUP[lowered]
        raise CalculationError(f"Unknown name '{node.id}'")
    if isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand, degrees, variables)
        number = _check_number(operand, "operand")
        if isinstance(node.op, ast.UAdd):
            return operand
        if isinstance(node.op, ast.USub):
            return -operand
        raise CalculationError("Unsupported unary operator")
    if isinstance(node, ast.BinOp):
        left = _eval_node(node.left, degrees, variables)
        right = _eval_node(node.right, degrees, variables)
        return _apply_binop(node.op, left, right)
    if isinstance(node, ast.Call):
        spec = _FUNCTION_LOOKUP[node.func.id.lower()]  # validated already
        args = [_eval_node(arg, degrees, variables) for arg in node.args]
        try:
            return spec.fn(args, degrees)
        except CalculationError:
            raise
        except ZeroDivisionError:
            raise CalculationError("Division by zero") from None
        except OverflowError:
            raise CalculationError("Result is too large to calculate") from None
        except ValueError:
            raise CalculationError(f"Math error in {spec.name}()") from None
    raise CalculationError("Unsupported syntax")


def _apply_binop(op: ast.operator, left: Any, right: Any) -> Any:
    if isinstance(op, ast.Add):
        return left + right
    if isinstance(op, ast.Sub):
        return left - right
    if isinstance(op, ast.Mult):
        try:
            return left * right
        except OverflowError:
            raise CalculationError("Result is too large to calculate") from None
    if isinstance(op, (ast.Div, ast.FloorDiv, ast.Mod)):
        if isinstance(right, (int, float)) and right == 0:
            raise CalculationError("Division by zero")
        try:
            if isinstance(op, ast.Div):
                return left / right
            if isinstance(op, ast.FloorDiv):
                return left // right
            return left % right
        except ZeroDivisionError:
            raise CalculationError("Division by zero") from None
        except OverflowError:
            raise CalculationError("Result is too large to calculate") from None
    if isinstance(op, ast.Pow):
        return _apply_pow(left, right)
    raise CalculationError("Unsupported operator")


def _apply_pow(base: Any, exponent: Any) -> Any:
    if isinstance(exponent, bool) or not isinstance(exponent, (int, float)):
        raise CalculationError("Exponent must be a number")
    if isinstance(base, bool) or not isinstance(base, (int, float)):
        raise CalculationError("Base must be a number")
    if isinstance(exponent, int) and abs(exponent) > MAX_INT_EXPONENT and abs(base) > 1:
        raise CalculationError("Exponent is too large")
    if isinstance(exponent, float) and not math.isfinite(exponent):
        raise CalculationError("Exponent is too large")
    if base == 0 and isinstance(exponent, (int, float)) and exponent < 0:
        raise CalculationError("Division by zero")
    try:
        result = base ** exponent
    except OverflowError:
        raise CalculationError("Result is too large to calculate") from None
    except ZeroDivisionError:
        raise CalculationError("Division by zero") from None
    if isinstance(result, complex):
        raise CalculationError("Result is not a real number")
    return result


def evaluate(
    expression: str,
    degrees: bool = True,
    variables: Mapping[str, Any] | None = None,
) -> int | float:
    """Evaluate *expression* and return the raw numeric result.

    Raises :class:`CalculationError` with a friendly message for anything the
    user needs to fix.  ``variables`` optionally binds extra names (used by the
    graphing sampler for ``x``); it never widens the AST allow-list.
    """
    source = normalise(expression) if isinstance(expression, str) else expression
    if not isinstance(source, str):
        raise CalculationError("Expression must be text")
    tree = _parse(source)
    _Validator(variables).visit(tree)
    result = _eval_node(tree, bool(degrees), dict(variables or {}))
    if isinstance(result, bool) or not isinstance(result, (int, float)):
        raise CalculationError("Result is not a number")
    if isinstance(result, float) and not math.isfinite(result):
        raise CalculationError("Result is too large to calculate")
    return result


# --------------------------------------------------------------------------- #
# The shared contract
# --------------------------------------------------------------------------- #
def _blank_result(expression: Any) -> dict[str, Any]:
    return {
        "ok": False,
        "value": None,
        "formatted": "",
        "tokens": tokenize(expression) if isinstance(expression, str) else [],
        "error": None,
    }


def calculate(expression: str, degrees: bool = True) -> dict[str, Any]:
    """Evaluate *expression* and return the shared result contract.

    ``{"ok": bool, "value": number|None, "formatted": str,
    "tokens": [...], "error": str|None}`` -- the very same shape the Flask JSON
    API hands out and the browser JS mirrors.  ``degrees`` switches trig
    input/output conversion only.

    This function never raises for bad user input; problems are reported through
    ``ok=False`` plus a friendly ``error`` string.
    """
    result = _blank_result(expression)
    if not isinstance(expression, str):
        result["error"] = "Expression must be text"
        return result

    try:
        source = normalise(expression)
    except CalculationError as exc:
        result["error"] = str(exc)
        return result

    tokens, token_error = _tokenise(source)
    result["tokens"] = tokens
    if token_error:
        result["error"] = token_error
        return result
    if not tokens:
        result["error"] = "Enter an expression to calculate"
        return result

    try:
        value = evaluate(source, degrees=degrees)
        formatted = format_number(value)
    except CalculationError as exc:
        result["error"] = str(exc)
        return result
    except (ArithmeticError, ValueError) as exc:  # pragma: no cover - safety net
        result["error"] = f"Could not calculate: {exc}"
        return result

    result["ok"] = True
    result["value"] = value
    result["formatted"] = formatted
    result["error"] = None
    return result

