/* ==========================================================================
   Numera — calculator bench
   --------------------------------------------------------------------------
   DESIGN NOTES
   The brief is an instrument, not a dashboard. So: figures are the hero,
   surfaces are matte and quiet, structure comes from hairlines and one
   accent thread rather than cards with soft shadows.

   Colour     ink #0A0F0F / panel #0F1615 / bone #F0EADD, with a single
              saturated accent per mode — cyan (scientific), amber (graphing),
              violet (date). The accent is the only saturated colour on screen;
              it lights the mode lamp, the thread, focus rings and the primary
              key. Everything else is bone-on-ink.

   Type       Two families, clearly distinct, both system stacks (offline):
              a serif for words (wordmark, headings, buttons) and a monospace
              for figures and instrument micro-labels. No sans-serif, no web
              fonts. Figures always use tabular-nums so digits never shift.

   Layout     A bench: sticky nameplate rail + segmented mode switch, a status
              rail that states the active mode and its accent, a wide stage for
              the panel, and a quiet foot. Generous outer margins, content
              edges aligned to the same vertical rule at every breakpoint.

   Motion     One orchestrated moment per mode change: the accent tokens morph,
              the status motif redraws, the thread sweeps. Nothing loops, and
              everything stops for prefers-reduced-motion.

   Modes      All colour tokens live on :root and are overridden by
              body[data-mode="…"], so a single attribute switch repaints the
              whole shell — used by app.js for the cross-fade before navigating.
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. Tokens
   -------------------------------------------------------------------------- */
:root {
  /* surfaces */
  --tone-page: #0a0f0f;
  --tone-panel: #0f1615;
  --tone-raise: #141c1b;
  --tone-key: #182220;
  --tone-key-hover: #202b29;
  --tone-key-active: #2a3735;
  --veil: rgba(10, 15, 15, 0.86);

  /* ink */
  --bone: #f0eadd;
  --bone-2: #c3bdaf;
  --bone-3: #968f84;
  --on-accent: #06191a;

  /* lines */
  --rule: rgba(240, 234, 221, 0.14);
  --rule-soft: rgba(240, 234, 221, 0.075);
  --rule-strong: rgba(240, 234, 221, 0.3);

  /* accent — overridden per mode below */
  --accent: #4fd1d9;
  --accent-soft: rgba(79, 209, 217, 0.14);
  --accent-line: rgba(79, 209, 217, 0.42);
  --accent-glow: rgba(79, 209, 217, 0.22);

  --danger: #ff9a8c;

  /* type */
  --font-text: "Iowan Old Style", "Charter", "Palatino Linotype", Palatino,
    "Book Antiqua", Georgia, "DejaVu Serif", ui-serif, serif;
  --font-mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", "Segoe UI Mono",
    "Roboto Mono", Menlo, Consolas, "DejaVu Sans Mono", monospace;

  --fs-micro: 0.6875rem;
  --fs-sm: 0.8125rem;
  --fs-body: clamp(0.97rem, 0.93rem + 0.18vw, 1.0625rem);
  --fs-lg: clamp(1.1rem, 1rem + 0.45vw, 1.3rem);
  --fs-title: clamp(1.5rem, 1.15rem + 1.5vw, 2.25rem);
  --fs-readout: clamp(2.1rem, 1.4rem + 3.6vw, 3.4rem);

  /* shape */
  --r-xs: 3px;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 18px;
  --r-pill: 999px;

  /* rhythm */
  --gutter: clamp(1rem, 0.55rem + 2.2vw, 2.5rem);
  --gap: clamp(0.85rem, 0.55rem + 1.1vw, 1.4rem);
  --gap-lg: clamp(1.4rem, 0.9rem + 2vw, 2.6rem);
  --measure: 68ch;
  --bench: 1240px;

  /* motion */
  --ease: cubic-bezier(0.22, 0.68, 0, 1);
  --dur-fast: 140ms;
  --dur: 260ms;
  --dur-slow: 520ms;

  /* depth: lit top edge + one soft ambient layer, never a big drop shadow */
  --lift: inset 0 1px 0 rgba(255, 255, 255, 0.035);
  --ambient: 0 18px 40px -32px rgba(0, 0, 0, 0.9);

  --focus-ring: 0 0 0 2px var(--tone-page), 0 0 0 4px var(--accent),
    0 0 0 8px var(--accent-soft);
}

body[data-mode="scientific"] {
  --accent: #4fd1d9;
  --accent-soft: rgba(79, 209, 217, 0.14);
  --accent-line: rgba(79, 209, 217, 0.42);
  --accent-glow: rgba(79, 209, 217, 0.24);
}

body[data-mode="graph"] {
  --accent: #f2b457;
  --accent-soft: rgba(242, 180, 87, 0.14);
  --accent-line: rgba(242, 180, 87, 0.42);
  --accent-glow: rgba(242, 180, 87, 0.24);
  --on-accent: #1d1203;
}

body[data-mode="date"] {
  --accent: #b79bf6;
  --accent-soft: rgba(183, 155, 246, 0.14);
  --accent-line: rgba(183, 155, 246, 0.42);
  --accent-glow: rgba(183, 155, 246, 0.24);
  --on-accent: #150a2c;
}

/* --------------------------------------------------------------------------
   2. Base
   -------------------------------------------------------------------------- */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scrollbar-color: var(--tone-key) var(--tone-page);
}

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  background-color: var(--tone-page);
  color: var(--bone);
  font-family: var(--font-text);
  font-size: var(--fs-body);
  line-height: 1.55;
  font-kerning: normal;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  transition: background-color var(--dur) var(--ease);
}

/* Faint instrument grid + warm vignette. Texture, not decoration: it stops the
   ink reading as flat #000 and gives the stage a surface to sit on. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(240, 234, 221, 0.022) 1px, transparent 1px),
    linear-gradient(90deg, rgba(240, 234, 221, 0.022) 1px, transparent 1px),
    radial-gradient(120% 80% at 50% -10%, rgba(240, 234, 221, 0.05), transparent 62%);
  background-size: 64px 64px, 64px 64px, 100% 100%;
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.9), rgba(0, 0, 0, 0.35) 70%);
}

body > * {
  position: relative;
  z-index: 1;
}

h1,
h2,
h3,
h4 {
  margin: 0;
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.012em;
  text-wrap: balance;
}

h1 {
  font-size: var(--fs-title);
}
h2 {
  font-size: var(--fs-lg);
}
h3 {
  font-size: var(--fs-body);
}

p {
  margin: 0;
  max-width: var(--measure);
  text-wrap: pretty;
}

a {
  color: var(--bone);
  text-decoration-color: var(--rule-strong);
  text-underline-offset: 0.22em;
  text-decoration-thickness: 1px;
}

a:hover {
  text-decoration-color: var(--accent);
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

::selection {
  background: var(--accent-soft);
  color: var(--bone);
}

svg {
  display: block;
}

/* Focus: a double ring in the mode accent, legible on every surface. */
:where(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--r-sm);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: var(--gutter);
  top: 0.5rem;
  z-index: 50;
  transform: translateY(-160%);
  padding: 0.5rem 0.9rem;
  border-radius: var(--r-sm);
  background: var(--accent);
  color: var(--on-accent);
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
  text-decoration: none;
  transition: transform var(--dur-fast) var(--ease);
}

.skip-link:focus-visible {
  transform: translateY(0);
}

/* --------------------------------------------------------------------------
   3. Shared text roles
   -------------------------------------------------------------------------- */
.meta {
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.07em;
  color: var(--bone-3);
  font-variant-numeric: tabular-nums;
}

/* Section label above a block of controls — sentence case, mono, quiet. */
.label {
  display: block;
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.08em;
  color: var(--bone-3);
  margin-bottom: 0.45rem;
}

.note {
  font-size: var(--fs-sm);
  color: var(--bone-3);
  line-height: 1.5;
}

kbd {
  font-family: var(--font-mono);
  font-size: 0.75em;
  padding: 0.12em 0.4em;
  border: 1px solid var(--rule);
  border-bottom-width: 2px;
  border-radius: var(--r-xs);
  background: var(--tone-raise);
  color: var(--bone-2);
}

/* --------------------------------------------------------------------------
   4. Rail (nameplate + mode switch)
   -------------------------------------------------------------------------- */
.rail {
  position: sticky;
  top: 0;
  z-index: 20;
  background: var(--veil);
  border-bottom: 1px solid var(--rule);
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  transition: border-color var(--dur) var(--ease), box-shadow var(--dur) var(--ease);
}

.rail.is-scrolled {
  box-shadow: 0 12px 24px -22px rgba(0, 0, 0, 1);
  border-bottom-color: var(--rule-soft);
}

.rail__inner {
  max-width: var(--bench);
  margin-inline: auto;
  padding: 0.75rem var(--gutter);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap);
  flex-wrap: wrap;
}

.nameplate {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  padding: 0.15rem 0.1rem;
  border-radius: var(--r-sm);
}

.nameplate__glyph {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  color: var(--accent);
  border: 1px solid var(--accent-line);
  border-radius: 50%;
  background: var(--accent-soft);
  transition: color var(--dur) var(--ease), border-color var(--dur) var(--ease),
    background-color var(--dur) var(--ease);
}

.nameplate__words {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.nameplate__word {
  font-size: 1.2rem;
  letter-spacing: 0.02em;
  font-weight: 500;
}

.nameplate__tag {
  font-family: var(--font-mono);
  font-size: 0.625rem;
  letter-spacing: 0.11em;
  color: var(--bone-3);
  margin-top: 0.18rem;
}

/* Segmented switch: one hairline capsule, three lamp-lit segments. */
.modes {
  display: flex;
  align-items: stretch;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  background: rgba(0, 0, 0, 0.28);
}

.mode-tab {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.44rem 0.85rem 0.44rem 0.7rem;
  border-radius: var(--r-pill);
  border: 1px solid transparent;
  color: var(--bone-2);
  text-decoration: none;
  white-space: nowrap;
  font-size: 0.9375rem;
  transition: color var(--dur-fast) var(--ease),
    background-color var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease);
}

.mode-tab__icon {
  color: var(--bone-3);
  transition: color var(--dur-fast) var(--ease);
}

.mode-tab__label {
  letter-spacing: 0.005em;
}

/* The lamp is the mode indicator: dark when idle, lit in the mode accent. */
.mode-tab__lamp {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--rule-strong);
  transition: background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.mode-tab:hover {
  color: var(--bone);
  background: rgba(240, 234, 221, 0.055);
}

.mode-tab:hover .mode-tab__icon {
  color: var(--bone-2);
}

.mode-tab.is-active {
  color: var(--bone);
  background: var(--accent-soft);
  border-color: var(--accent-line);
}

.mode-tab.is-active .mode-tab__icon {
  color: var(--accent);
}

.mode-tab.is-active .mode-tab__lamp {
  background: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft), 0 0 9px var(--accent-glow);
}

/* --------------------------------------------------------------------------
   5. Status rail — states the mode and its accent, carries the motif
   -------------------------------------------------------------------------- */
.statusbar {
  border-bottom: 1px solid var(--rule-soft);
  background: linear-gradient(180deg, rgba(240, 234, 221, 0.028), transparent);
}

.statusbar__inner {
  max-width: var(--bench);
  margin-inline: auto;
  padding: 0.7rem var(--gutter) 0.75rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap);
  flex-wrap: wrap;
}

.statusbar__now {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  min-width: 0;
}

/* All three motifs are in the DOM; CSS reveals the one matching data-mode so
   the swap happens instantly during the JS cross-fade. */
.motifs {
  display: block;
  color: var(--accent);
  flex: 0 0 auto;
  transition: color var(--dur) var(--ease);
}

.motif {
  display: none;
  overflow: visible;
}

body[data-mode="scientific"] .motif[data-motif="scientific"],
body[data-mode="graph"] .motif[data-motif="graph"],
body[data-mode="date"] .motif[data-motif="date"] {
  display: block;
}

.motif__trace {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: trace-in var(--dur-slow) var(--ease) 120ms forwards;
}

.motif__rule {
  animation: fade-in var(--dur) var(--ease) both;
}

.motif__dot {
  opacity: 0;
  animation: fade-in var(--dur) var(--ease) 420ms forwards;
}

.statusbar__text {
  display: flex;
  align-items: baseline;
  gap: 0.6rem;
  flex-wrap: wrap;
  min-width: 0;
}

.statusbar__label {
  font-size: 0.9375rem;
  letter-spacing: 0.01em;
  color: var(--bone);
}

.statusbar__label::after {
  content: "";
  display: inline-block;
  width: 1px;
  height: 0.85em;
  margin-left: 0.6rem;
  background: var(--accent);
  vertical-align: -0.06em;
  opacity: 0.6;
  transition: background-color var(--dur) var(--ease);
}

.statusbar__blurb {
  font-size: var(--fs-sm);
  color: var(--bone-3);
  max-width: 46ch;
}

.statusbar__meta {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  flex-wrap: wrap;
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  color: var(--bone-2);
  font-variant-numeric: tabular-nums;
}

.accent-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.2rem 0.55rem 0.2rem 0.35rem;
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  background: rgba(0, 0, 0, 0.3);
}

.accent-chip__swatch {
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 2px;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent-glow);
  transition: background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.accent-chip__name {
  color: var(--bone);
}

.statusbar__step {
  color: var(--bone-3);
  letter-spacing: 0.04em;
}

.statusbar__step-now {
  color: var(--bone-2);
}

/* The single bold device: one accent thread under the status rail. */
.statusbar__thread {
  height: 2px;
  transform-origin: 0 50%;
  background: linear-gradient(
    90deg,
    var(--accent) 0%,
    var(--accent) 38%,
    var(--accent-line) 68%,
    transparent 100%
  );
  animation: thread-in 720ms var(--ease) both;
  transition: background var(--dur) var(--ease);
}

/* --------------------------------------------------------------------------
   6. Stage
   -------------------------------------------------------------------------- */
.stage {
  flex: 1 1 auto;
  width: 100%;
  max-width: var(--bench);
  margin-inline: auto;
  padding: var(--gap-lg) var(--gutter) var(--gap-lg);
  display: grid;
  gap: var(--gap);
  align-content: start;
}

.stage:focus {
  outline: none;
}

/* Page-enter: one orchestrated reveal, not a per-element cascade. */
.rail,
.statusbar__inner,
.stage,
.foot {
  animation: rise var(--dur-slow) var(--ease) both;
}

.statusbar__inner {
  animation-delay: 40ms;
}
.stage {
  animation-delay: 80ms;
}
.foot {
  animation-delay: 120ms;
}

/* --------------------------------------------------------------------------
   7. Panel primitives (used by the scientific / graph / date templates)
   -------------------------------------------------------------------------- */
.panel {
  border: 1px solid var(--rule);
  border-radius: var(--r-lg);
  background:
    linear-gradient(180deg, rgba(240, 234, 221, 0.028), transparent 42%),
    var(--tone-panel);
  box-shadow: var(--lift), var(--ambient);
  padding: clamp(1rem, 0.7rem + 1.1vw, 1.6rem);
  display: grid;
  gap: var(--gap);
  align-content: start;
  min-width: 0;
}

.panel--quiet {
  background: transparent;
  box-shadow: none;
  border-style: dashed;
}

.panel__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--gap);
  flex-wrap: wrap;
  padding-bottom: 0.7rem;
  border-bottom: 1px solid var(--rule-soft);
}

.panel__title {
  font-size: var(--fs-lg);
}

.panel__hint {
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  color: var(--bone-3);
}

/* Two-column bench: instrument on the left, readings on the right. */
.cols {
  display: grid;
  gap: var(--gap);
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
}

@media (min-width: 900px) {
  .cols {
    grid-template-columns: minmax(0, 1.25fr) minmax(0, 0.75fr);
  }
  .cols--even {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .cols--wide-right {
    grid-template-columns: minmax(0, 0.72fr) minmax(0, 1.28fr);
  }
}

.stack {
  display: grid;
  gap: var(--gap);
  align-content: start;
  min-width: 0;
}

.stack--tight {
  gap: 0.5rem;
}

.row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.row--end {
  justify-content: flex-end;
}

/* ---- readout: the hero figure ------------------------------------------- */
.readout {
  display: grid;
  gap: 0.35rem;
  padding: 0.9rem 1rem 1rem;
  border: 1px solid var(--rule-soft);
  border-radius: var(--r-md);
  background:
    linear-gradient(180deg, rgba(0, 0, 0, 0.42), rgba(0, 0, 0, 0.18)),
    var(--tone-raise);
  box-shadow: inset 0 1px 0 rgba(240, 234, 221, 0.045), inset 0 -18px 30px -30px #000;
  min-width: 0;
}

.readout__label {
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.08em;
  color: var(--bone-3);
}

.readout__value {
  font-family: var(--font-mono);
  font-size: var(--fs-readout);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
  line-height: 1.08;
  letter-spacing: -0.02em;
  color: var(--bone);
  text-align: right;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
  overflow-wrap: normal;
  white-space: nowrap;
  font-variant-ligatures: none;
  padding-block: 0.1rem;
}

.readout__value.is-accent {
  color: var(--accent);
}

.readout__value.is-error {
  color: var(--danger);
  font-size: clamp(1rem, 0.9rem + 0.6vw, 1.2rem);
  letter-spacing: 0;
  white-space: normal;
  text-align: right;
  line-height: 1.4;
}

.readout__expression {
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
  font-variant-numeric: tabular-nums;
  color: var(--bone-3);
  text-align: right;
  overflow-wrap: anywhere;
}

/* ---- keys --------------------------------------------------------------- */
.keypad {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.keypad--wide {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.key {
  appearance: none;
  border: 1px solid var(--rule-soft);
  border-radius: var(--r-sm);
  background: var(--tone-key);
  box-shadow: var(--lift);
  color: var(--bone);
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.9375rem;
  min-height: 2.7rem;
  padding: 0.4rem 0.3rem;
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease),
    color var(--dur-fast) var(--ease),
    transform var(--dur-fast) var(--ease);
}

.key:hover {
  background: var(--tone-key-hover);
  border-color: var(--rule);
}

.key:active {
  background: var(--tone-key-active);
  transform: translateY(1px);
}

.key--fn {
  color: var(--bone-2);
  font-size: 0.8125rem;
  background: var(--tone-raise);
}

.key--op {
  color: var(--accent);
  background: var(--tone-raise);
  border-color: var(--accent-line);
}

.key--equals {
  color: var(--on-accent);
  background: var(--accent);
  border-color: var(--accent);
  font-weight: 600;
  box-shadow: 0 6px 18px -14px var(--accent), var(--lift);
  transition: background-color var(--dur) var(--ease),
    border-color var(--dur) var(--ease), color var(--dur) var(--ease),
    transform var(--dur-fast) var(--ease);
}

.key--equals:hover {
  background: color-mix(in srgb, var(--accent) 88%, #fff);
}

.key--span-2 {
  grid-column: span 2;
}

/* ---- buttons ------------------------------------------------------------ */
.btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.5rem 0.95rem;
  border: 1px solid var(--rule);
  border-radius: var(--r-sm);
  background: var(--tone-raise);
  color: var(--bone);
  font-family: var(--font-text);
  font-size: 0.9375rem;
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease);
}

.btn:hover {
  background: var(--tone-key-hover);
  border-color: var(--rule-strong);
}

.btn--primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
  font-weight: 600;
  transition: background-color var(--dur) var(--ease),
    border-color var(--dur) var(--ease), color var(--dur) var(--ease);
}

.btn--primary:hover {
  background: color-mix(in srgb, var(--accent) 88%, #fff);
  border-color: transparent;
}

.btn--quiet {
  background: transparent;
  border-color: transparent;
  color: var(--bone-3);
  padding-inline: 0.5rem;
}

.btn--quiet:hover {
  color: var(--bone);
  background: rgba(240, 234, 221, 0.06);
}

.btn--small {
  font-size: var(--fs-sm);
  padding: 0.32rem 0.6rem;
}

.btn[aria-pressed="true"] {
  border-color: var(--accent-line);
  background: var(--accent-soft);
  color: var(--accent);
}

/* ---- fields ------------------------------------------------------------- */
.field {
  display: grid;
  gap: 0.3rem;
  min-width: 0;
}

.input,
.select {
  width: 100%;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--rule);
  border-radius: var(--r-sm);
  background: rgba(0, 0, 0, 0.34);
  box-shadow: inset 0 1px 0 rgba(0, 0, 0, 0.4);
  color: var(--bone);
  font-family: var(--font-mono);
  font-size: 0.9375rem;
  font-variant-numeric: tabular-nums;
  transition: border-color var(--dur-fast) var(--ease),
    background-color var(--dur-fast) var(--ease);
}

.input::placeholder {
  color: var(--bone-3);
  opacity: 1;
}

.input:hover,
.select:hover {
  border-color: var(--rule-strong);
}

.input:focus-visible,
.select:focus-visible {
  border-color: var(--accent);
  box-shadow: var(--focus-ring);
}

.input--expression {
  font-size: clamp(1.05rem, 0.95rem + 0.5vw, 1.3rem);
  padding: 0.75rem 0.85rem;
  letter-spacing: 0.01em;
}

.select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--bone-3) 50%),
    linear-gradient(135deg, var(--bone-3) 50%, transparent 50%);
  background-position: calc(100% - 15px) calc(50% + 1px), calc(100% - 10px) calc(50% + 1px);
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 2rem;
}

/* ---- chips, badges, data lists ------------------------------------------ */
.chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.16rem 0.5rem;
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.05em;
  color: var(--bone-2);
  background: rgba(0, 0, 0, 0.26);
  font-variant-numeric: tabular-nums;
}

.chip--accent {
  border-color: var(--accent-line);
  background: var(--accent-soft);
  color: var(--accent);
}

/* Terms-and-values list: hairline rows, mono figures right-aligned. */
.data {
  display: grid;
  margin: 0;
  border-top: 1px solid var(--rule-soft);
}

.data > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--gap);
  padding: 0.5rem 0.1rem;
  border-bottom: 1px solid var(--rule-soft);
}

.data dt {
  font-size: var(--fs-sm);
  color: var(--bone-3);
  flex: 0 0 auto;
}

.data dd {
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
  font-variant-numeric: tabular-nums;
  color: var(--bone);
  text-align: right;
  overflow-wrap: anywhere;
}

.data dd.is-accent {
  color: var(--accent);
}

/* History rows keep a stable numeric column. */
.history {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 2px;
  max-height: 22rem;
  overflow-y: auto;
}

.history li {
  display: grid;
  gap: 0.1rem;
  padding: 0.45rem 0.55rem;
  border-radius: var(--r-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease);
}

.history li:hover,
.history li:focus-visible {
  background: rgba(240, 234, 221, 0.05);
  border-color: var(--rule-soft);
}

.history__expression {
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
  color: var(--bone-3);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.history__result {
  font-family: var(--font-mono);
  font-size: 0.9375rem;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.empty {
  padding: 1rem 0.2rem;
  font-size: var(--fs-sm);
  color: var(--bone-3);
  border-top: 1px solid var(--rule-soft);
}

/* ---- plot frame --------------------------------------------------------- */
.plot {
  position: relative;
  border: 1px solid var(--rule-soft);
  border-radius: var(--r-md);
  background: rgba(0, 0, 0, 0.34);
  box-shadow: inset 0 1px 0 rgba(0, 0, 0, 0.5);
  overflow: hidden;
}

.plot canvas,
.plot svg {
  display: block;
  width: 100%;
  height: auto;
}

.hair {
  height: 1px;
  border: 0;
  margin: 0;
  background: var(--rule-soft);
}

/* --------------------------------------------------------------------------
   8. Foot
   -------------------------------------------------------------------------- */
.foot {
  max-width: var(--bench);
  width: 100%;
  margin-inline: auto;
  padding: 1rem var(--gutter) 2rem;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: var(--gap);
  flex-wrap: wrap;
  border-top: 1px solid var(--rule-soft);
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.05em;
  color: var(--bone-3);
}

.foot kbd {
  letter-spacing: 0;
}

/* --------------------------------------------------------------------------
   9. Mode-change cross-fade (app.js sets body[data-mode] + .is-switching)
   -------------------------------------------------------------------------- */
body.is-switching {
  cursor: progress;
}

body.is-switching .mode-tab.is-active {
  background: var(--accent-soft);
  border-color: var(--accent-line);
}

body.is-switching .statusbar__label,
body.is-switching .statusbar__blurb {
  animation: swap-text var(--dur) var(--ease) both;
}

body.is-switching .statusbar__thread {
  animation: thread-in var(--dur) var(--ease) both;
}

/* --------------------------------------------------------------------------
   10. Motion
   -------------------------------------------------------------------------- */
@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes trace-in {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes thread-in {
  from {
    transform: scaleX(0.04);
    opacity: 0.2;
  }
  to {
    transform: scaleX(1);
    opacity: 1;
  }
}

@keyframes swap-text {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }

  .motif__trace {
    stroke-dashoffset: 0;
  }

  .motif__dot {
    opacity: 1;
  }

  .statusbar__thread {
    transform: none;
  }
}

/* --------------------------------------------------------------------------
   11. Responsive
   -------------------------------------------------------------------------- */
@media (max-width: 760px) {
  .rail__inner {
    padding-block: 0.6rem;
  }

  .nameplate__tag {
    display: none;
  }

  .modes {
    order: 3;
    flex: 1 1 100%;
    justify-content: space-between;
  }

  .mode-tab {
    flex: 1 1 0;
    justify-content: center;
    padding-inline: 0.5rem;
  }

  .statusbar__blurb {
    display: none;
  }

  .statusbar__label::after {
    display: none;
  }
}

@media (max-width: 560px) {
  .statusbar__meta {
    width: 100%;
    justify-content: space-between;
  }

  .stage {
    padding-top: var(--gap);
  }

  .panel {
    padding: 0.9rem 0.8rem 1rem;
    border-radius: var(--r-md);
  }

  .foot {
    flex-direction: column;
    gap: 0.35rem;
  }
}

@media (max-width: 400px) {
  :root {
    --gutter: 0.85rem;
  }

  .mode-tab {
    gap: 0.35rem;
    font-size: 0.8125rem;
  }

  .mode-tab__icon svg {
    width: 16px;
    height: 16px;
  }

  .motif {
    width: 34px;
    height: 20px;
  }

  .keypad--wide {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .key {
    min-height: 2.5rem;
    font-size: 0.875rem;
  }
}

/* Anything narrower than a phone: let the switch scroll instead of squashing. */
@media (max-width: 360px) {
  .modes {
    overflow-x: auto;
    scrollbar-width: none;
  }

  .mode-tab__label {
    font-size: 0.75rem;
  }
}

@media (prefers-contrast: more) {
  :root {
    --rule: rgba(240, 234, 221, 0.32);
    --rule-soft: rgba(240, 234, 221, 0.2);
    --bone-2: #ded8ca;
    --bone-3: #c3bdaf;
  }
}

@media print {
  body::before,
  .rail,
  .statusbar,
  .foot {
    display: none;
  }

  body {
    background: #fff;
    color: #000;
  }
}

/* ==========================================================================
   Numera — shell controller
   --------------------------------------------------------------------------
   Owns everything that is shared by the three panels:

     • the segmented mode switch (role="tablist"): click + arrow-key handling,
       an accent cross-fade before navigating, so switching modes reads as one
       continuous instrument rather than three unrelated pages
     • the status rail (mode name, blurb, accent name, position)
     • a polite live region the panels can push messages into

   Panels talk to it through `window.Numera`:

     Numera.mode                       -> "scientific" | "graph" | "date"
     Numera.meta                       -> { label, accent, blurb, route, index }
     Numera.reducedMotion              -> boolean (live)
     Numera.announce(text)             -> polite screen-reader message
     Numera.fetchJSON(url, payload)    -> { ok, status, data }
     Numera.formatNumber(value, sig)   -> fixed-significant-figure string
     Numera.ready(fn)                  -> run fn once the DOM is parsed

   No dependencies, no globals besides `Numera`. Everything is queried
   defensively so the file is safe in a standalone preview that omits the
   JSON metadata block.
   ========================================================================== */
(function () {
  "use strict";

  var MODE_ORDER = ["scientific", "graph", "date"];

  /* Fallback copy if #mode-meta is absent (standalone preview). */
  var FALLBACK = {
    scientific: {
      label: "Scientific",
      route: "/",
      accent: "cyan",
      blurb: "Type an expression; functions, constants and history live here.",
      index: 1
    },
    graph: {
      label: "Graphing",
      route: "/graph",
      accent: "amber",
      blurb: "Plot one or more curves and read their shape against the axes.",
      index: 2
    },
    date: {
      label: "Date",
      route: "/date",
      accent: "violet",
      blurb: "Work the calendar: intervals, offsets, workdays and birthdays.",
      index: 3
    }
  };

  var body = document.body;
  var docEl = document.documentElement;
  var SWITCH_MS = 300;

  var reduceQuery =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)")
      : null;

  /* ---------------------------------------------------------------- meta -- */
  var meta = readMeta();

  function readMeta() {
    var data = {};
    Object.keys(FALLBACK).forEach(function (key) {
      data[key] = Object.assign({}, FALLBACK[key]);
    });

    var node = document.getElementById("mode-meta");
    if (node) {
      try {
        var parsed = JSON.parse(node.textContent || "{}");
        Object.keys(parsed).forEach(function (key) {
          if (parsed[key] && typeof parsed[key] === "object") {
            data[key] = Object.assign(data[key] || {}, parsed[key]);
          }
        });
      } catch (error) {
        /* Malformed JSON: keep the fallback copy. */
      }
    }
    return data;
  }

  function currentMode() {
    var mode = body.getAttribute("data-mode");
    return meta[mode] ? mode : MODE_ORDER[0];
  }

  /* ---------------------------------------------------------------- refs -- */
  var tablist = document.querySelector("[data-mode-tabs]");
  var tabs = tablist
    ? Array.prototype.slice.call(tablist.querySelectorAll('[role="tab"]'))
    : [];

  var statusLabel = document.querySelector("[data-status-label]");
  var statusBlurb = document.querySelector("[data-status-blurb]");
  var statusIndex = document.querySelector("[data-status-index]");
  var accentName = document.querySelector("[data-accent-name]");
  var announceRegion = document.querySelector("[data-announce]");
  var rail = document.querySelector(".rail");

  function tabFor(mode) {
    for (var i = 0; i < tabs.length; i += 1) {
      if (tabs[i].getAttribute("data-mode-target") === mode) return tabs[i];
    }
    return null;
  }

  /* ------------------------------------------------------------ statusbar -- */
  /* Keeps the rail honest about the active mode — also covers a preview where
     the markup was copied without the server-rendered labels. */
  function syncStatus(mode) {
    var info = meta[mode] || {};
    if (statusLabel && info.label) statusLabel.textContent = info.label;
    if (statusBlurb && info.blurb) statusBlurb.textContent = info.blurb;
    if (accentName && info.accent) accentName.textContent = info.accent;
    if (statusIndex && info.index) statusIndex.textContent = String(info.index);
    if (tabs.length) {
      tabs.forEach(function (tab) {
        var isActive = tab.getAttribute("data-mode-target") === mode;
        tab.setAttribute("aria-selected", isActive ? "true" : "false");
        tab.classList.toggle("is-active", isActive);
        if (isActive) {
          tab.setAttribute("aria-current", "page");
        } else {
          tab.removeAttribute("aria-current");
        }
      });
    }
  }

  /* ------------------------------------------------------------ switching -- */
  var switching = false;

  function go(target) {
    var info = meta[target];
    if (!info || !info.route || switching) return;

    var mode = currentMode();
    if (target === mode) return;

    if (reducedMotion() || !statusLabel) {
      window.location.assign(info.route);
      return;
    }

    /* Repaint the chrome in the target accent, play the cross-fade, then
       navigate. The next page arrives already wearing that accent, so the
       transition reads as one continuous change rather than a page load. */
    switching = true;
    body.classList.remove("is-switching");
    void body.offsetWidth; /* restart the text/thread animations */
    body.setAttribute("data-mode", target);
    body.classList.add("is-switching");
    syncStatus(target);
    announce(info.label + " mode");

    window.setTimeout(function () {
      window.location.assign(info.route);
    }, SWITCH_MS + 40);
  }

  function reducedMotion() {
    return !!(reduceQuery && reduceQuery.matches);
  }

  if (tablist) {
    tablist.addEventListener("click", function (event) {
      var tab = event.target.closest ? event.target.closest('[role="tab"]') : null;
      if (!tab || !tablist.contains(tab)) return;
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      if (typeof event.button === "number" && event.button !== 0) return;
      event.preventDefault();
      go(tab.getAttribute("data-mode-target"));
    });

    /* Tabs are real links, so Enter/Space already work. Arrow keys move focus
       between them (manual activation, matching the "roving" pattern). */
    tablist.addEventListener("keydown", function (event) {
      var index = tabs.indexOf(document.activeElement);
      if (index === -1) return;
      var next = -1;

      switch (event.key) {
        case "ArrowRight":
        case "ArrowDown":
          next = (index + 1) % tabs.length;
          break;
        case "ArrowLeft":
        case "ArrowUp":
          next = (index - 1 + tabs.length) % tabs.length;
          break;
        case "Home":
          next = 0;
          break;
        case "End":
          next = tabs.length - 1;
          break;
        default:
          return;
      }

      event.preventDefault();
      tabs[next].focus();
    });
  }

  /* Numeric shortcut: 1/2/3 jump between modes when the user is not typing. */
  document.addEventListener("keydown", function (event) {
    if (event.altKey || event.ctrlKey || event.metaKey) return;
    if (event.key !== "1" && event.key !== "2" && event.key !== "3") return;
    var el = event.target;
    if (el && el.closest && el.closest("input, textarea, select, [contenteditable='']")) return;
    if (el && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName))) return;
    var target = MODE_ORDER[Number(event.key) - 1];
    if (target) {
      event.preventDefault();
      go(target);
    }
  });

  /* ------------------------------------------------------------- announce -- */
  function announce(message) {
    if (!announceRegion || !message) return;
    /* Re-set the text so repeated identical messages are still announced. */
    announceRegion.textContent = "";
    window.setTimeout(function () {
      announceRegion.textContent = String(message);
    }, 60);
  }

  /* ----------------------------------------------------------------- fetch -- */
  function fetchJSON(url, payload) {
    return fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify(payload || {})
    })
      .then(function (response) {
        return response
          .json()
          .catch(function () {
            return { ok: false, error: "Unexpected response from the server." };
          })
          .then(function (data) {
            return { ok: response.ok, status: response.status, data: data };
          });
      })
      .catch(function () {
        return {
          ok: false,
          status: 0,
          data: { ok: false, error: "Could not reach the calculator service." }
        };
      });
  }

  /* --------------------------------------------------------------- format -- */
  /* Twelve significant figures, trailing zeros trimmed, integers kept plain.
     Panels use this for figures so digits always align in mono columns. */
  function formatNumber(value, digits) {
    var sig = typeof digits === "number" ? digits : 12;
    var number = typeof value === "number" ? value : Number(value);
    if (!isFinite(number)) return "—";
    if (Number.isInteger(number) && Math.abs(number) < 1e15) return String(number);

    var abs = Math.abs(number);
    var text;
    if (abs !== 0 && (abs < 1e-9 || abs >= 1e12)) {
      text = number.toExponential(sig - 1).replace(/(\.\d*?)0+e/, "$1e").replace(/\.e/, "e");
      return text.replace("e+", "e");
    }
    text = number.toPrecision(sig);
    if (text.indexOf(".") !== -1) {
      text = text.replace(/0+$/, "").replace(/\.$/, "");
    }
    return text;
  }

  /* ------------------------------------------------------------------ boot -- */
  function ready(fn) {
    if (docEl.getAttribute("data-booting") === null && document.readyState !== "loading") {
      fn();
    } else {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    }
  }

  /* Rail hairline tightening once the page scrolls: a quiet affordance that the
     nameplate is pinned. */
  function watchScroll() {
    if (!rail) return;
    var ticking = false;
    function update() {
      rail.classList.toggle("is-scrolled", window.scrollY > 4);
      ticking = false;
    }
    window.addEventListener(
      "scroll",
      function () {
        if (ticking) return;
        ticking = true;
        window.requestAnimationFrame(update);
      },
      { passive: true }
    );
    update();
  }

  syncStatus(currentMode());
  watchScroll();

  window.Numera = {
    get mode() {
      return currentMode();
    },
    get meta() {
      return meta[currentMode()];
    },
    get modes() {
      return meta;
    },
    get reducedMotion() {
      return reducedMotion();
    },
    announce: announce,
    fetchJSON: fetchJSON,
    formatNumber: formatNumber,
    go: go,
    ready: ready
  };
})();

