            i += 1
            while i < n and src[i].isalpha(): i += 1
            prev_sig = 're'
            continue
    if c in '([{':
        stack.append((c, line))
    elif c in ')]}':
        if not stack or stack[-1][0] != pairs[c]:
            errs.append('unmatched %r at line %d (stack top %r)' % (c, line, stack[-1] if stack else None))
        else:
            stack.pop()
    if not c.isspace():
        prev_sig = c
    i += 1
print('unclosed:', stack)
print('errors:', errs or 'none')
print('lines:', src.count('\n')+1)
