/* --------------------------------------------------------------------------
   12. Panel instruments (scientific + date)
   --------------------------------------------------------------------------
   Everything the two panels introduce builds on section 7 and reads its colour
   from the mode tokens, so a body[data-mode] switch repaints all of it.

     entry      .exprbar .tokens .token (--number/--name/--operator/--lparen/
                --rparen/--comma/--error, plus .is-function) .is-hidden
     toggles    .seg .seg__btn            (DEG/RAD, aria-pressed)
                .subtabs .subtab           (Difference / Add-subtract, aria-selected)
     keypad     .keypad--sci .keypad__rule .key--num .key--const .key--act .key--warn
     figures    .readout__badge .readout__unit .daycount
     visuals    .viz .viz__head .viz__title .viz__note .viz__legend .viz__swatch
     forms      .pair .presets .presets__label
     history    .history__btn .history__meta .history__result.is-error
   -------------------------------------------------------------------------- */
.is-hidden {
  display: none !important;
}

/* ---- expression entry ---------------------------------------------------- */
.tokens {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 3px;
  align-content: flex-start;
  min-height: 2.1rem;
  padding: 0.32rem 0.4rem;
  border: 1px dashed var(--rule-soft);
  border-radius: var(--r-sm);
  background: rgba(0, 0, 0, 0.22);
}

.tokens:empty::after {
  content: "tokens appear here as you type";
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  color: var(--bone-3);
}

.token {
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
  line-height: 1.3;
  padding: 0 0.28rem;
  border: 1px solid transparent;
  border-radius: var(--r-xs);
  color: var(--bone-2);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.token--number {
  color: var(--bone);
  background: rgba(240, 234, 221, 0.09);
}

.token--name {
  color: var(--bone-2);
  background: rgba(240, 234, 221, 0.045);
}

.token--name.is-function {
  color: var(--accent);
  background: transparent;
}

.token--operator {
  color: var(--accent);
  border-color: var(--accent-line);
  background: var(--accent-soft);
}

.token--lparen,
.token--rparen,
.token--comma {
  color: var(--bone-3);
  background: rgba(240, 234, 221, 0.03);
}

.token--error {
  color: var(--danger);
  border-color: var(--danger);
  background: rgba(255, 154, 140, 0.12);
}

/* ---- segmented toggles (DEG/RAD) ---------------------------------------- */
.seg {
  display: inline-flex;
  padding: 2px;
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  background: rgba(0, 0, 0, 0.32);
}

.seg__btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: var(--r-pill);
  background: transparent;
  color: var(--bone-3);
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.08em;
  padding: 0.3rem 0.62rem;
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease);
}

.seg__btn:hover {
  color: var(--bone);
}

.seg__btn[aria-pressed="true"] {
  color: var(--accent);
  background: var(--accent-soft);
  border-color: var(--accent-line);
}

/* ---- inner tabs (date sub-modes) --------------------------------------- */
.subtabs {
  display: inline-flex;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  background: rgba(0, 0, 0, 0.32);
}

.subtab {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  appearance: none;
  border: 1px solid transparent;
  border-radius: var(--r-pill);
  background: transparent;
  color: var(--bone-3);
  font-family: var(--font-text);
  font-size: var(--fs-sm);
  padding: 0.34rem 0.85rem;
  cursor: pointer;
  transition: background-color var(--dur) var(--ease),
    border-color var(--dur) var(--ease), color var(--dur) var(--ease);
}

.subtab:hover {
  color: var(--bone);
}

.subtab.is-active {
  color: var(--accent);
  background: var(--accent-soft);
  border-color: var(--accent-line);
}

.subtab__lamp {
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.26;
  transition: opacity var(--dur) var(--ease), box-shadow var(--dur) var(--ease);
}

.subtab.is-active .subtab__lamp {
  opacity: 1;
  box-shadow: 0 0 0 3px var(--accent-soft);
}

/* ---- keypad ------------------------------------------------------------- */
.keypad--sci {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 5px;
}

.keypad__rule {
  grid-column: 1 / -1;
  height: 1px;
  margin-block: 0.12rem;
  background: var(--rule-soft);
}

.key--num {
  color: var(--bone);
  font-size: 1.02rem;
}

.key--const {
  color: var(--accent);
  background: var(--tone-raise);
}

.key--act {
  color: var(--bone-2);
  background: var(--tone-raise);
  font-size: 0.8125rem;
}

.key--warn {
  color: var(--danger);
  border-color: rgba(255, 154, 140, 0.26);
  background: var(--tone-raise);
  font-size: 0.8125rem;
}

/* ---- figures ------------------------------------------------------------ */
.readout__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-left: 0.45rem;
  padding: 0.02rem 0.42rem;
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  color: var(--bone-3);
  vertical-align: 0.06em;
}

.readout__badge::before {
  content: "";
  width: 0.34rem;
  height: 0.34rem;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.85;
}

.readout__badge.is-accent {
  color: var(--accent);
  border-color: var(--accent-line);
  background: var(--accent-soft);
}

.readout__badge.is-warn {
  color: var(--danger);
  border-color: rgba(255, 154, 140, 0.3);
}

.daycount {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 0.45rem;
  flex-wrap: wrap;
}

.readout__unit {
  font-family: var(--font-mono);
  font-size: var(--fs-lg);
  letter-spacing: 0.02em;
  color: var(--bone-3);
}

/* ---- visualisation frame ------------------------------------------------ */
.viz {
  display: grid;
  gap: 0.45rem;
  margin: 0;
  min-width: 0;
}

.viz__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.viz__title {
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--bone-3);
}

.viz__note {
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.04em;
  color: var(--bone-3);
  font-variant-numeric: tabular-nums;
}

.viz__note.is-accent {
  color: var(--accent);
}

.plot > .viz__canvas {
  display: block;
  width: 100%;
  height: 168px;
}

.viz--tall .plot > .viz__canvas {
  height: 196px;
}

.viz__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 0.9rem;
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.04em;
  color: var(--bone-3);
}

.viz__legend > span {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.viz__swatch {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 2px;
  background: var(--accent);
}

.viz__swatch--mute {
  background: rgba(240, 234, 221, 0.26);
}

.viz__swatch--bone {
  background: var(--bone-2);
}

.viz__swatch--line {
  height: 2px;
  border-radius: 1px;
  background: var(--accent);
}

/* ---- forms -------------------------------------------------------------- */
.pair {
  display: grid;
  gap: 0.6rem;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
}

.input--date {
  color-scheme: dark;
}

.presets {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.presets__label {
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.08em;
  color: var(--bone-3);
  margin-right: 0.15rem;
}

/* ---- history rows ------------------------------------------------------- */
.history__btn {
  appearance: none;
  display: grid;
  gap: 0.1rem;
  width: 100%;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.history__btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--r-xs);
}

.history__meta {
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.05em;
  color: var(--bone-3);
  font-variant-numeric: tabular-nums;
}

.history__result.is-error {
  color: var(--danger);
  font-size: var(--fs-sm);
}

/* Narrow phones: keep five keypad columns (the rows are the muscle memory),
   shrink the glyphs instead of reflowing them. */
@media (max-width: 560px) {
  .keypad--sci {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 4px;
  }

  .keypad--sci .key {
    min-height: 2.35rem;
    font-size: 0.75rem;
    padding-inline: 0.15rem;
  }

  .keypad--sci .key--num {
    font-size: 0.9375rem;
  }
}

@media (max-width: 460px) {
  .pair {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-contrast: more) {
  .token--lparen,
  .token--rparen,
  .token--comma,
  .token--name {
    color: var(--bone-2);
  }
}
