/* ==========================================================================
   Numera — scientific panel
   --------------------------------------------------------------------------
   Two layers in one file:

   1. THE MIRROR  (normalise / tokenize / parse / evaluate / formatNumber)
      A dependency-free re-implementation of the contract served by
      calculators/engine.py through POST /api/calculate:

          { ok, value, formatted, tokens, error }

      It runs on every keystroke so the readout never lags, and it is what
      fills the panel when the request fails (offline, 501, bad gateway).
      The server answer always wins when it arrives: the token strip is then
      rendered from the server's own token list.

   2. THE PANEL   (token strip, keypad, DEG/RAD, debounced request,
      localStorage history capped at 20, canvas parse-tree visualisation)

   Only the panel hooks exposed by templates/scientific.html are queried, and
   every query is null-safe, so the file degrades quietly if markup changes.
   ========================================================================== */
(function () {
  "use strict";

  var HISTORY_KEY = "numera.history.scientific";
  var HISTORY_MAX = 20;
  var DEBOUNCE_MS = 220;
  var MAX_TREE_TOKENS = 80;

  /* ====================================================================== */
  /* 1. The mirror: maths                                                      */
  /* ====================================================================== */
  function CalculationError(message) {
    var error = new Error(message);
    error.calculation = true;
    return error;
  }

  function toNumber(value, what) {
    if (typeof value !== "number" || !isFinite(value)) {
      throw CalculationError((what || "Value") + " must be a number");
    }
    return value;
  }

  var CONSTANTS = { pi: Math.PI, e: Math.E, tau: Math.PI * 2 };
  var FACTORIAL_MAX = 1000;
  var EXPONENT_MAX = 10000;

  function factorial(n) {
    var value = toNumber(n);
    if (value < 0) throw CalculationError("Factorial of a negative number");
    if (value !== Math.floor(value)) throw CalculationError("Factorial needs a whole number");
    var number = Math.floor(value);
    if (number > FACTORIAL_MAX) {
      throw CalculationError("Factorial input is too large (max " + FACTORIAL_MAX + ")");
    }
    var out = 1;
    for (var i = 2; i <= number; i += 1) out *= i;
    return out;
  }

  function combination(n, r, permutations) {
    var total = toNumber(n, "n");
    var chosen = toNumber(r, "r");
    if (total < 0 || total !== Math.floor(total)) {
      throw CalculationError("n must be a whole number of at least 0");
    }
    if (chosen < 0 || chosen !== Math.floor(chosen)) {
      throw CalculationError("r must be a whole number of at least 0");
    }
    if (chosen > total) throw CalculationError("r cannot be larger than n");
    if (total > FACTORIAL_MAX) {
      throw CalculationError("n is too large (max " + FACTORIAL_MAX + ")");
    }
    var out = 1;
    var k = Math.floor(chosen);
    var top = Math.floor(total);
    for (var i = 0; i < k; i += 1) {
      out = (out * (top - i)) / (i + 1);
    }
    if (!permutations) return Math.round(out);
    var perm = Math.round(out);
    for (var j = 0; j < k; j += 1) perm *= k - j;
    return perm;
  }

  function logWithBase(args) {
    var value = toNumber(args[0]);
    if (value <= 0) throw CalculationError("Logarithm needs a positive number");
    if (args.length < 2) return Math.log10(value);
    var base = toNumber(args[1], "Base");
    if (base <= 0 || base === 1) throw CalculationError("Base must be positive and not 1");
    return Math.log(value) / Math.log(base);
  }

  function sqrtOf(args) {
    var value = toNumber(args[0]);
    if (value < 0) throw CalculationError("Cannot take the square root of a negative number");
    return Math.sqrt(value);
  }

  function roundTo(args) {
    var value = toNumber(args[0]);
    if (args.length < 2) return Math.round(value);
    var digits = toNumber(args[1], "Digit count");
    if (digits !== Math.floor(digits)) throw CalculationError("round needs a whole number of digits");
    if (Math.abs(digits) > 15) throw CalculationError("round supports at most 15 digits");
    var factor = Math.pow(10, Math.max(0, Math.min(15, Math.floor(digits))));
    return Math.round(value * factor) / factor;
  }

  /* Degree-mode trigonometry keeps exact values at the quadrant boundaries so
     sin(90) is 1 rather than 0.9999999999999999 (the Python engine does the
     same, and the two must agree). */
  function degMod(value) {
    var rest = value % 360;
    return rest < 0 ? rest + 360 : rest;
  }

  function sinOf(args, degrees) {
    var value = toNumber(args[0]);
    if (!degrees) return Math.sin(value);
    var rest = degMod(value);
    if (rest === 0 || rest === 180) return 0;
    if (rest === 90) return 1;
    if (rest === 270) return -1;
    return Math.sin((value * Math.PI) / 180);
  }

  function cosOf(args, degrees) {
    var value = toNumber(args[0]);
    if (!degrees) return Math.cos(value);
    var rest = degMod(value);
    if (rest === 0) return 1;
    if (rest === 90 || rest === 270) return 0;
    if (rest === 180) return -1;
    return Math.cos((value * Math.PI) / 180);
  }

  function tanOf(args, degrees) {
    var value = toNumber(args[0]);
    if (!degrees) return Math.tan(value);
    var rest = degMod(value);
    if (rest === 90 || rest === 270) {
      throw CalculationError("Tangent is undefined at 90° + 180°·k");
    }
    if (rest === 0 || rest === 180) return 0;
    return Math.tan((value * Math.PI) / 180);
  }

  function asinOf(args, degrees) {
    var value = toNumber(args[0]);
    if (value < -1 || value > 1) throw CalculationError("asin needs a value between -1 and 1");
    var out = Math.asin(value);
    return degrees ? (out * 180) / Math.PI : out;
  }

  function acosOf(args, degrees) {
    var value = toNumber(args[0]);
    if (value < -1 || value > 1) throw CalculationError("acos needs a value between -1 and 1");
    var out = Math.acos(value);
    return degrees ? (out * 180) / Math.PI : out;
  }

  function atanOf(args, degrees) {
    var out = Math.atan(toNumber(args[0]));
    return degrees ? (out * 180) / Math.PI : out;
  }

  function guardDomain(name, value) {
    if (!isFinite(value)) throw CalculationError(name + " is not defined here");
    return value;
  }

  var FUNCTIONS = {
    sin: { min: 1, max: 1, fn: sinOf },
    cos: { min: 1, max: 1, fn: cosOf },
    tan: { min: 1, max: 1, fn: tanOf },
    asin: { min: 1, max: 1, fn: asinOf },
    acos: { min: 1, max: 1, fn: acosOf },
    atan: { min: 1, max: 1, fn: atanOf },
    sinh: { min: 1, max: 1, fn: function (a) { return Math.sinh(toNumber(a[0])); } },
    cosh: { min: 1, max: 1, fn: function (a) { return Math.cosh(toNumber(a[0])); } },
    tanh: { min: 1, max: 1, fn: function (a) { return Math.tanh(toNumber(a[0])); } },
    asinh: { min: 1, max: 1, fn: function (a) { return Math.asinh(toNumber(a[0])); } },
    acosh: { min: 1, max: 1, fn: function (a) {
      var v = toNumber(a[0]);
      if (v < 1) throw CalculationError("acosh needs a value of at least 1");
      return Math.acosh(v);
    } },
    atanh: { min: 1, max: 1, fn: function (a) {
      var v = toNumber(a[0]);
      if (v <= -1 || v >= 1) throw CalculationError("atanh needs a value between -1 and 1");
      return Math.atanh(v);
    } },
    log: { min: 1, max: 2, fn: logWithBase },
    ln: { min: 1, max: 1, fn: function (a) {
      var v = toNumber(a[0]);
      if (v <= 0) throw CalculationError("Logarithm needs a positive number");
      return Math.log(v);
    } },
    log2: { min: 1, max: 1, fn: function (a) {
      var v = toNumber(a[0]);
      if (v <= 0) throw CalculationError("Logarithm needs a positive number");
      return Math.log2(v);
    } },
    log10: { min: 1, max: 1, fn: function (a) {
      var v = toNumber(a[0]);
      if (v <= 0) throw CalculationError("Logarithm needs a positive number");
      return Math.log10(v);
    } },
    exp: { min: 1, max: 1, fn: function (a) { return guardDomain("exp", Math.exp(toNumber(a[0]))); } },
    sqrt: { min: 1, max: 1, fn: sqrtOf },
    cbrt: { min: 1, max: 1, fn: function (a) {
      var v = toNumber(a[0]);
      return Math.cbrt ? Math.cbrt(v) : Math.sign(v) * Math.pow(Math.abs(v), 1 / 3);
    } },
    abs: { min: 1, max: 1, fn: function (a) { return Math.abs(toNumber(a[0])); } },
    floor: { min: 1, max: 1, fn: function (a) { return Math.floor(toNumber(a[0])); } },
    ceil: { min: 1, max: 1, fn: function (a) { return Math.ceil(toNumber(a[0])); } },
    round: { min: 1, max: 2, fn: roundTo },
    factorial: { min: 1, max: 1, fn: function (a) { return factorial(a[0]); } },
    ncr: { min: 2, max: 2, fn: function (a) { return combination(a[0], a[1], false); } },
    npr: { min: 2, max: 2, fn: function (a) { return combination(a[0], a[1], true); } }
  };

  /* ====================================================================== */
  /* 2. The mirror: normalise, tokenise, parse, evaluate, format              */
  /* ====================================================================== */
  var CHAR_MAP = {
    "×": "*", "·": "*", "⋅": "*", "∙": "*", "∗": "*",
    "÷": "/", "⁄": "/", "∕": "/",
    "−": "-", "–": "-", "—": "-", "‐": "-",
    "^": "**",
    "²": "**2", "³": "**3",
    "√": "sqrt", "π": "pi", "τ": "tau",
    "（": "(", "）": ")", "，": ",", "。": ".",
    "\u0000": " "
  };

  function normalise(expression) {
    var text = typeof expression === "string" ? expression : "";
    var out = "";
    for (var i = 0; i < text.length; i += 1) {
      var ch = text.charAt(i);
      out += Object.prototype.hasOwnProperty.call(CHAR_MAP, ch) ? CHAR_MAP[ch] : ch;
    }
    out = out.replace(/[\r\n\t]/g, " ").replace(/^\s+/, "");
    out = out.replace(/\s+$/, "");
    while (out.charAt(out.length - 1) === "=") {
      out = out.slice(0, -1).replace(/\s+$/, "");
    }
    return out;
  }

  var TOKEN_RE = /(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?|[A-Za-z_][A-Za-z_0-9]*|\*\*|\/\/|[-+*/%^]|\(|\)|,|\.|\s+/g;
  var NUMBER_RE = /^(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?$/;
  var NAME_RE = /^[A-Za-z_][A-Za-z_0-9]*$/;
  var SPACE_RE = /^\s+$/;

  function tokenizeRaw(source) {
    var tokens = [];
    var error = null;
    var position = 0;
    while (position < source.length) {
      TOKEN_RE.lastIndex = position;
      var match = TOKEN_RE.exec(source);
      if (!match || match.index !== position) {
        var bad = source.charAt(position);
        tokens.push({ type: "error", text: bad, value: null, start: position });
        if (error === null) {
          error = "Unexpected character '" + bad + "' at position " + (position + 1);
        }
        position += 1;
        continue;
      }
      var text = match[0];
      var start = position;
      position = match.index + text.length;
      if (SPACE_RE.test(text)) continue;
      if (NUMBER_RE.test(text)) {
        tokens.push({ type: "number", text: text, value: parseFloat(text), start: start });
      } else if (NAME_RE.test(text)) {
        tokens.push({ type: "name", text: text, value: null, start: start });
      } else if (text === "(") {
        tokens.push({ type: "lparen", text: text, value: null, start: start });
      } else if (text === ")") {
        tokens.push({ type: "rparen", text: text, value: null, start: start });
      } else if (text === ",") {
        tokens.push({ type: "comma", text: text, value: null, start: start });
      } else if (text === ".") {
        tokens.push({ type: "error", text: text, value: null, start: start });
        if (error === null) error = "Unexpected character '.' at position " + (start + 1);
      } else {
        tokens.push({ type: "operator", text: text, value: null, start: start });
      }
    }
    return { tokens: tokens, error: error };
  }

  function tokenize(expression) {
    var source = normalise(expression);
    if (!source) return [];
    return tokenizeRaw(source).tokens;
  }

  /* Recursive-descent parser producing a small AST for evaluation *and* for
     the canvas tree.  Mirrors Python's precedence:
       add  <  mul (incl. // and %)  <  unary  <  power (right assoc.)  <  postfix ! */
  function parseTokens(tokens) {
    var index = 0;

    function peek() {
      return tokens[index] || null;
    }

    function isOp(token, text) {
      return !!token && token.type === "operator" && token.text === text;
    }

    function expect(type, message) {
      var token = peek();
      if (!token || token.type !== type) throw CalculationError(message);
      index += 1;
      return token;
    }

    function parseAdd() {
      var node = parseMul();
      while (peek() && peek().type === "operator" && (peek().text === "+" || peek().text === "-")) {
        var op = tokens[index].text;
        index += 1;
        node = { type: "binary", op: op, left: node, right: parseMul() };
      }
      return node;
    }

    function parseMul() {
      var node = parseUnary();
      while (
        peek() &&
        peek().type === "operator" &&
        (peek().text === "*" || peek().text === "/" || peek().text === "//" || peek().text === "%")
      ) {
        var op = tokens[index].text;
        index += 1;
        node = { type: "binary", op: op, left: node, right: parseUnary() };
      }
      return node;
    }

    function parseUnary() {
      var token = peek();
      if (isOp(token, "-") || isOp(token, "+")) {
        index += 1;
        return { type: "unary", op: token.text, arg: parseUnary() };
      }
      return parsePower();
    }

    function parsePower() {
      var node = parsePostfix();
      if (isOp(peek(), "**")) {
        index += 1;
        node = { type: "binary", op: "**", left: node, right: parseUnary() };
      }
      return node;
    }

    function parsePostfix() {
      var node = parsePrimary();
      while (isOp(peek(), "!")) {
        index += 1;
        node = { type: "postfix", op: "!", arg: node };
      }
      return node;
    }

    function parsePrimary() {
      var token = peek();
      if (!token) throw CalculationError("Expression is incomplete");

      if (token.type === "number") {
        index += 1;
        return { type: "number", text: token.text, value: token.value };
      }

      if (token.type === "name") {
        index += 1;
        var name = token.text;
        var lower = name.toLowerCase();
        if (peek() && peek().type === "lparen") {
          var spec = FUNCTIONS[lower];
          if (!spec) throw CalculationError("Unknown function '" + name + "'");
          index += 1;
          var args = [];
          if (!(peek() && peek().type === "rparen")) {
            args.push(parseAdd());
            while (peek() && peek().type === "comma") {
              index += 1;
              args.push(parseAdd());
            }
          }
          expect("rparen", "Missing a closing bracket for " + name + "(");
          if (args.length < spec.min || args.length > spec.max) {
            throw CalculationError(
              spec.min === spec.max
                ? name + "() takes " + spec.min + " argument" + (spec.min === 1 ? "" : "s")
                : name + "() takes " + spec.min + " to " + spec.max + " arguments"
            );
          }
          return { type: "call", name: lower, label: name, args: args };
        }
        if (Object.prototype.hasOwnProperty.call(CONSTANTS, lower)) {
          return { type: "constant", name: lower, value: CONSTANTS[lower] };
        }
        throw CalculationError("Unknown name '" + name + "'");
      }

      if (token.type === "lparen") {
        index += 1;
        var inner = parseAdd();
        expect("rparen", "Missing a closing bracket");
        return inner;
      }

      if (token.type === "rparen") throw CalculationError("Unbalanced brackets");
      if (token.type === "comma") throw CalculationError("Unexpected comma");
      if (token.type === "operator") {
        throw CalculationError("Operator '" + token.text + "' is missing a value");
      }
      throw CalculationError("Unexpected '" + token.text + "'");
    }

    if (!tokens.length) throw CalculationError("Enter an expression");
    var tree = parseAdd();
    if (index < tokens.length) {
      var stray = tokens[index];
      if (stray.type === "rparen") throw CalculationError("Unbalanced brackets");
      throw CalculationError("Unexpected '" + stray.text + "'");
    }
    return tree;
  }

  function evaluateAst(node, degrees) {
    switch (node.type) {
      case "number":
      case "constant":
        return node.value;
      case "call": {
        var spec = FUNCTIONS[node.name];
        var args = node.args.map(function (arg) {
          return evaluateAst(arg, degrees);
        });
        return toNumber(spec.fn(args, degrees), "Result");
      }
      case "unary": {
        var inner = evaluateAst(node.arg, degrees);
        return node.op === "-" ? -inner : inner;
      }
      case "postfix":
        return factorial(evaluateAst(node.arg, degrees));
      case "binary": {
        var left = evaluateAst(node.left, degrees);
        var right = evaluateAst(node.right, degrees);
        switch (node.op) {
          case "+":
            return left + right;
          case "-":
            return left - right;
          case "*":
            return left * right;
          case "/":
            if (right === 0) throw CalculationError("Division by zero");
            return left / right;
          case "//":
            if (right === 0) throw CalculationError("Division by zero");
            return Math.floor(left / right);
          case "%":
            if (right === 0) throw CalculationError("Division by zero");
            return left % right;
          case "**": {
            if (Math.abs(right) > EXPONENT_MAX) {
              throw CalculationError("Exponent is too large");
            }
            var powered = Math.pow(left, right);
            if (!isFinite(powered)) throw CalculationError("Result is too large");
            return powered;
          }
          default:
            throw CalculationError("Unknown operator '" + node.op + "'");
        }
      }
      default:
        throw CalculationError("Could not evaluate this expression");
    }
  }

  function formatNumber(value) {
    if (typeof value !== "number" || !isFinite(value)) {
      throw CalculationError("Result is not a finite number");
    }
    if (Number.isInteger(value) && Math.abs(value) < 1e12) return String(value);
    if (value === 0) return "0";
    var abs = Math.abs(value);
    if (abs >= 1e-9 && abs < 1e12) {
      var adjusted = Math.floor(Math.log(abs) / Math.LN10);
      if (Math.pow(10, adjusted) > abs) adjusted -= 1;
      var decimals = Math.max(0, Math.min(100, 11 - adjusted));
      var text = value.toFixed(decimals);
      if (text.indexOf(".") !== -1) text = text.replace(/0+$/, "").replace(/\.$/, "");
      if (text === "" || text === "-" || text === "-0") return "0";
      return text;
    }
    var parts = value.toExponential(11).split("e");
    var mantissa = parts[0].replace(/0+$/, "").replace(/\.$/, "");
    if (mantissa === "" || mantissa === "-" || mantissa === "-0") mantissa = "0";
    return mantissa + "e" + String(Number(parts[1]));
  }

  /* The Python engine keeps integers exact and rounds floats to 12 significant
     digits, so chained calculations start from the number on screen. */
  function roundValue(value) {
    if (typeof value !== "number" || !isFinite(value)) return value;
    if (Number.isInteger(value) && Math.abs(value) < 1e15) return value;
    return Number(value.toPrecision(12));
  }

  function calculate(expression, degrees) {
    var source = normalise(expression);
    var tokens = [];
    if (!source) {
      return { ok: false, value: null, formatted: "", tokens: tokens, error: "Enter an expression" };
    }
    var scanned = tokenizeRaw(source);
    tokens = scanned.tokens;
    if (scanned.error) {
      return { ok: false, value: null, formatted: "", tokens: tokens, error: scanned.error };
    }
    try {
      var tree = parseTokens(tokens);
      var raw = evaluateAst(tree, degrees !== false);
      var value = roundValue(raw);
      return {
        ok: true,
        value: value,
        formatted: formatNumber(value),
        tokens: tokens,
        tree: tree,
        error: null
      };
    } catch (error) {
      return {
        ok: false,
        value: null,
        formatted: "",
        tokens: tokens,
        tree: null,
        error: error && error.calculation ? error.message : "Could not evaluate this expression"
      };
    }
  }

  function parseStructure(expression) {
    var source = normalise(expression);
    if (!source) return { ok: true, tree: null, tokens: [], error: null };
    var scanned = tokenizeRaw(source);
    if (scanned.error) return { ok: false, tree: null, tokens: scanned.tokens, error: scanned.error };
    try {
      return { ok: true, tree: parseTokens(scanned.tokens), tokens: scanned.tokens, error: null };
    } catch (error) {
      return {
        ok: false,
        tree: null,
        tokens: scanned.tokens,
        error: error && error.calculation ? error.message : "Could not read this expression"
      };
    }
  }

  /* ====================================================================== */
  /* 3. Panel state + helpers                                                 */
  /* ====================================================================== */
  var shell = window.Numera || null;

  function ready(fn) {
    if (shell && typeof shell.ready === "function") shell.ready(fn);
    else if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else fn();
  }

  function announce(message) {
    if (shell && typeof shell.announce === "function") shell.announce(message);
  }

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = String(text);
    return node;
  }

  function formatTime(stamp) {
    if (!stamp) return "";
    var date = new Date(stamp);
    if (isNaN(date.getTime())) return "";
    var hours = String(date.getHours());
    var minutes = String(date.getMinutes());
    if (hours.length < 2) hours = "0" + hours;
    if (minutes.length < 2) minutes = "0" + minutes;
    return hours + ":" + minutes;
  }

  var state = {
    degrees: true,
    expression: "",
    local: null,
    server: null,
    history: [],
    sequence: 0,
    timer: 0,
    source: "local"
  };

  var refs = {};

  function collect() {
    refs.form = document.querySelector("[data-sci-form]");
    refs.input = document.querySelector("[data-expression]");
    refs.tokens = document.querySelector("[data-tokens]");
    refs.keypad = document.querySelector("[data-keypad]");
    refs.angleButtons = document.querySelectorAll("[data-angle]");
    refs.value = document.querySelector("[data-result-value]");
    refs.badge = document.querySelector("[data-result-badge]");
    refs.expression = document.querySelector("[data-result-expression]");
    refs.engineChip = document.querySelector("[data-engine-chip]");
    refs.treeCanvas = document.querySelector("[data-tree-canvas]");
    refs.treeNote = document.querySelector("[data-tree-note]");
    refs.detailAngle = document.querySelector("[data-detail-angle]");
    refs.detailRaw = document.querySelector("[data-detail-raw]");
    refs.detailTokens = document.querySelector("[data-detail-tokens]");
    refs.detailEngine = document.querySelector("[data-detail-engine]");
    refs.history = document.querySelector("[data-history]");
    refs.historyEmpty = document.querySelector("[data-history-empty]");
    refs.historyCount = document.querySelector("[data-history-count]");
    refs.historyClear = document.querySelector("[data-history-clear]");
  }

  /* ------------------------------------------------------------- history -- */
  function loadHistory() {
    var raw = null;
    try {
      raw = window.localStorage.getItem(HISTORY_KEY);
    } catch (error) {
      raw = null;
    }
    if (!raw) return [];
    try {
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed
        .filter(function (entry) {
          return entry && typeof entry.expression === "string";
        })
        .slice(0, HISTORY_MAX)
        .map(function (entry) {
          return {
            expression: entry.expression,
            formatted: typeof entry.formatted === "string" ? entry.formatted : "",
            ok: entry.ok !== false,
            angle: entry.angle === "rad" ? "rad" : "deg",
            at: typeof entry.at === "number" ? entry.at : Date.now()
          };
        });
    } catch (error) {
      return [];
    }
  }

  function saveHistory() {
    try {
      window.localStorage.setItem(HISTORY_KEY, JSON.stringify(state.history));
    } catch (error) {
      /* Private mode or a full quota: the session list still works. */
    }
  }

  function pushHistory(entry) {
    state.history = state.history.filter(function (item) {
      return item.expression !== entry.expression || item.angle !== entry.angle;
    });
    state.history.unshift(entry);
    if (state.history.length > HISTORY_MAX) state.history.length = HISTORY_MAX;
    saveHistory();
    renderHistory();
  }

  function renderHistory() {
    if (!refs.history) return;
    while (refs.history.firstChild) refs.history.removeChild(refs.history.firstChild);

    state.history.forEach(function (entry, index) {
      var item = el("li");
      var button = el("button", "history__btn");
      button.type = "button";
      button.setAttribute("data-index", String(index));
      button.setAttribute(
        "aria-label",
        "Reuse " + entry.expression + ", result " + (entry.formatted || "error")
      );
      button.appendChild(el("span", "history__expression", entry.expression));
      button.appendChild(
        el("span", "history__result" + (entry.ok ? "" : " is-error"), entry.formatted || "error")
      );
      button.appendChild(
        el("span", "history__meta", entry.angle + " · " + formatTime(entry.at))
      );
      item.appendChild(button);
      refs.history.appendChild(item);
    });

    if (refs.historyCount) {
      refs.historyCount.textContent = state.history.length + " / " + HISTORY_MAX;
    }
    if (refs.historyEmpty) {
      if (state.history.length) refs.historyEmpty.classList.add("is-hidden");
      else refs.historyEmpty.classList.remove("is-hidden");
    }
  }

  /* ---------------------------------------------------------------- paint -- */
  function setBadge(text, tone) {
    state.source = tone || "local";
    if (refs.badge) {
      refs.badge.textContent = text;
      refs.badge.classList.remove("is-accent", "is-warn");
      if (tone === "api") refs.badge.classList.add("is-accent");
      if (tone === "error") refs.badge.classList.add("is-warn");
    }
    if (refs.engineChip) {
      refs.engineChip.textContent = tone === "api" ? "api verified" : tone === "error" ? "check input" : "local engine";
    }
    if (refs.detailEngine) {
      refs.detailEngine.textContent = tone === "api" ? "api" : "local";
    }
  }

  function renderTokens(tokens) {
    if (!refs.tokens) return;
    while (refs.tokens.firstChild) refs.tokens.removeChild(refs.tokens.firstChild);
    (tokens || []).forEach(function (token, index) {
      var kind = token && token.type ? token.type : "error";
      var text = token && typeof token.text === "string" ? token.text : "";
      var next = tokens[index + 1];
      var isCall = kind === "name" && next && next.type === "lparen";
      var chip = el("span", "token token--" + kind + (isCall ? " is-function" : ""), text);
      refs.tokens.appendChild(chip);
    });
    if (refs.detailTokens) {
      refs.detailTokens.textContent = String((tokens || []).length);
    }
  }

  function paintResult(result, options) {
    var opts = options || {};
    var empty = !state.expression.trim();

    if (refs.value) {
      refs.value.classList.remove("is-error", "is-accent");
      if (empty) {
        refs.value.textContent = "0";
      } else if (result && result.ok) {
        refs.value.textContent = result.formatted;
      } else {
        refs.value.textContent = (result && result.error) || "Not a valid expression";
        refs.value.classList.add("is-error");
      }
    }

    if (refs.expression) {
      var source = normalise(state.expression);
      var typed = state.expression.trim();
      refs.expression.textContent =
        empty ? "" : source && source !== typed ? "reads as " + source : typed;
    }

    if (refs.detailRaw) {
      if (result && result.ok && typeof result.value === "number") {
        refs.detailRaw.textContent = formatNumber(result.value);
      } else {
        refs.detailRaw.textContent = "—";
      }
    }

    renderTokens(opts.tokens || (result && result.tokens) || []);

    if (empty) setBadge("live", "local");
    else if (result && !result.ok) setBadge("error", "error");
    else if (opts.source === "api") setBadge("verified", "api");
    else setBadge("live", "local");

    drawTree(opts.tree === undefined ? (result && result.tree) || null : opts.tree, opts.treeNote);
    announce(
      empty
        ? "Expression cleared"
        : result && result.ok
        ? "Result " + result.formatted
        : "Error: " + ((result && result.error) || "invalid expression")
    );
  }

  /* ----------------------------------------------------------- evaluation -- */
  function evaluateLocal() {
    var result = calculate(state.expression, state.degrees);
    state.local = result;
    return result;
  }

  function askServer(expression) {
    if (!expression) return;
    var sequence = state.sequence + 1;
    state.sequence = sequence;
    var url = (shell && shell.meta && shell.meta.api) || "/api/calculate";
    var body = { expression: expression, angle_mode: state.degrees ? "deg" : "rad" };

    var request =
      shell && typeof shell.fetchJSON === "function"
        ? shell.fetchJSON(url, body)
        : fetch(url, {
            method: "POST",
            headers: { "Content-Type": "application/json", Accept: "application/json" },
            body: JSON.stringify(body)
          }).then(function (response) {
            return response.json().then(function (data) {
              return { ok: response.ok, status: response.status, data: data };
            });
          });

    request
      .then(function (response) {
        if (sequence !== state.sequence) return;
        var payload = response && response.data;
        var result = payload && payload.result;
        if (response && response.ok && result && typeof result.ok === "boolean") {
          state.server = result;
          var structure = parseStructure(expression);
          paintResult(result, {
            source: "api",
            tokens: Array.isArray(result.tokens) && result.tokens.length ? result.tokens : undefined,
            tree: structure.tree,
            treeNote: treeNote(structure)
          });
          return;
        }
        /* 501 / 400 / network: the local engine keeps the panel alive. */
        var local = state.local || evaluateLocal();
        var fallback = parseStructure(expression);
        paintResult(local, {
          source: "local",
          tree: fallback.tree,
          treeNote: treeNote(fallback)
        });
        if (refs.engineChip) refs.engineChip.textContent = "local fallback";
      })
      .catch(function () {
        if (sequence !== state.sequence) return;
        var local = state.local || calculate(state.expression, state.degrees);
        paintResult(local, { source: "local" });
        if (refs.engineChip) refs.engineChip.textContent = "local fallback";
      });
  }

  function scheduleServer(expression) {
    window.clearTimeout(state.timer);
    state.timer = window.setTimeout(function () {
      askServer(expression);
    }, DEBOUNCE_MS);
  }

  function handleInput(options) {
    var opts = options || {};
    if (refs.input) state.expression = refs.input.value;
    var local = evaluateLocal();
    var structure = parseStructure(state.expression);
    paintResult(local, {
      source: "local",
      tree: structure.tree,
      treeNote: treeNote(structure)
    });
    if (opts.server !== false) scheduleServer(state.expression.trim());
  }

  /* --------------------------------------------------------------- commit -- */
  function commit() {
    var expression = state.expression.trim();
    if (!expression) {
      announce("Nothing to evaluate yet");
      return;
    }
    var local = evaluateLocal();
    pushHistory({
      expression: expression,
      formatted: local.ok ? local.formatted : local.error || "error",
      ok: local.ok,
      angle: state.degrees ? "deg" : "rad",
      at: Date.now()
    });
    announce(
      local.ok ? expression + " equals " + local.formatted : "Error: " + local.error
    );
    window.clearTimeout(state.timer);
    askServer(expression);
  }

  /* ------------------------------------------------------------- editing -- */
  function setExpression(text, options) {
    if (!refs.input) return;
    refs.input.value = text;
    var opts = options || {};
    if (opts.caret !== false) {
      var end = text.length;
      try {
        refs.input.setSelectionRange(end, end);
      } catch (error) {
        /* Older browsers: caret placement is a nicety. */
      }
    }
    handleInput();
  }

  function insertText(text) {
    if (!refs.input) return;
    var start = typeof refs.input.selectionStart === "number" ? refs.input.selectionStart : refs.input.value.length;
    var end = typeof refs.input.selectionEnd === "number" ? refs.input.selectionEnd : start;
    if (typeof refs.input.setRangeText === "function") {
      refs.input.setRangeText(text, start, end, "end");
    } else {
      var value = refs.input.value;
      refs.input.value = value.slice(0, start) + text + value.slice(end);
    }
    refs.input.focus({ preventScroll: true });
    handleInput();
  }

  function backspace() {
    if (!refs.input) return;
    var start = typeof refs.input.selectionStart === "number" ? refs.input.selectionStart : refs.input.value.length;
    var end = typeof refs.input.selectionEnd === "number" ? refs.input.selectionEnd : start;
    if (start !== end) {
      refs.input.setRangeText("", start, end, "end");
    } else if (start > 0) {
      refs.input.setRangeText("", start - 1, start, "end");
    }
    refs.input.focus({ preventScroll: true });
    handleInput();
  }

  function toggleSign() {
    var text = state.expression.trim();
    if (!text) return;
    if (/^-\(.*\)$/.test(text)) {
      var inner = text.slice(2, -1);
      setExpression(inner);
    } else {
      setExpression("-(" + text + ")");
    }
  }

  function clearAll() {
    setExpression("");
    if (refs.input) refs.input.focus({ preventScroll: true });
    announce("Expression cleared");
  }

  function setAngle(mode) {
    var degrees = mode !== "rad";
    if (degrees === state.degrees) return;
    state.degrees = degrees;
    for (var i = 0; i < refs.angleButtons.length; i += 1) {
      var button = refs.angleButtons[i];
      var isActive = button.getAttribute("data-angle") === (degrees ? "deg" : "rad");
      button.setAttribute("aria-pressed", isActive ? "true" : "false");
    }
    if (refs.detailAngle) refs.detailAngle.textContent = degrees ? "Degrees" : "Radians";
    announce(degrees ? "Degrees" : "Radians");
    handleInput();
  }

  /* ====================================================================== */
  /* 4. Canvas: the parse tree                                                */
  /* ====================================================================== */
  var NODE_H = 18;
  var NODE_PAD = 7;
  var NODE_GAP = 11;
  var ROW_H = 42;
  var MIN_NODE_W = 20;

  function labelFor(node) {
    switch (node.type) {
      case "number":
        return node.text.length > 9 ? node.text.slice(0, 8) + "…" : node.text;
      case "constant":
        return node.name;
      case "call":
        return node.label || node.name;
      case "unary":
        return node.op === "-" ? "neg" : "pos";
      case "postfix":
        return "!";
      case "binary": {
        if (node.op === "*") return "×";
        if (node.op === "/") return "÷";
        if (node.op === "//") return "⌊÷⌋";
        if (node.op === "%") return "mod";
        if (node.op === "**") return "^";
        if (node.op === "-") return "−";
        return node.op;
      }
      default:
        return "?";
    }
  }

  function toneFor(node) {
    if (node.type === "number") return "mute";
    if (node.type === "constant") return "bone";
    if (node.type === "call") return "accent";
    return "line";
  }

  function childrenOf(node) {
    if (node.type === "binary") return [node.left, node.right];
    if (node.type === "unary" || node.type === "postfix") return [node.arg];
    if (node.type === "call") return node.args.slice();
    return [];
  }

  function countNodes(node) {
    if (!node) return 0;
    return 1 + childrenOf(node).reduce(function (total, child) {
      return total + countNodes(child);
    }, 0);
  }

  function measureNode(ctx, node) {
    node.label = labelFor(node);
    node.kids = childrenOf(node);
    var textWidth = ctx.measureText(node.label).width + NODE_PAD * 2;
    var own = Math.max(MIN_NODE_W, textWidth);
    if (!node.kids.length) {
      node.kidsWidth = 0;
      node.width = own;
      return node.width;
    }
    var sum = 0;
    node.kids.forEach(function (child, index) {
      sum += measureNode(ctx, child);
      if (index) sum += NODE_GAP;
    });
    node.kidsWidth = sum;
    node.width = Math.max(own, sum);
    return node.width;
  }

  function placeNode(node, left, top, depth) {
    node.left = left;
    node.top = top;
    node.centerX = left + node.width / 2;
    node.depth = depth;
    if (!node.kids.length) return;
    var x = left + (node.width - node.kidsWidth) / 2;
    node.kids.forEach(function (child) {
      placeNode(child, x, top + ROW_H, depth + 1);
      x += child.width + NODE_GAP;
    });
  }

  function maxDepth(node) {
    if (!node || !node.kids.length) return 0;
    return (
      1 +
      node.kids.reduce(function (deepest, child) {
        return Math.max(deepest, maxDepth(child));
      }, 0)
    );
  }

  function roundRect(ctx, x, y, width, height, radius) {
    var r = Math.min(radius, width / 2, height / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + width - r, y);
    ctx.quadraticCurveTo(x + width, y, x + width, y + r);
    ctx.lineTo(x + width, y + height - r);
    ctx.quadraticCurveTo(x + width, y + height, x + width - r, y + height);
    ctx.lineTo(x + r, y + height);
    ctx.quadraticCurveTo(x, y + height, x, y + height - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function drawCenteredMessage(ctx, width, height, message) {
    ctx.fillStyle = colours().bone3;
    ctx.font = "12px " + monoStack();
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(message, width / 2, height / 2);
  }

  var colourCache = null;

  function colours() {
    if (colourCache) return colourCache;
    var style = window.getComputedStyle(document.body);
    function read(name, fallback) {
      var value = style.getPropertyValue(name);
      return value && value.trim() ? value.trim() : fallback;
    }
    colourCache = {
      accent: read("--accent", "#4fd1d9"),
      accentLine: read("--accent-line", "rgba(79,209,217,0.42)"),
      accentSoft: read("--accent-soft", "rgba(79,209,217,0.14)"),
      bone: read("--bone", "#f0eadd"),
      bone2: read("--bone-2", "#c3bdaf"),
      bone3: read("--bone-3", "#968f84"),
      rule: read("--rule", "rgba(240,234,221,0.14)")
    };
    return colourCache;
  }

  function monoStack() {
    return 'ui-monospace, "SFMono-Regular", "Cascadia Mono", Menlo, Consolas, monospace';
  }

  function toneColor(tone) {
    var c = colours();
    if (tone === "accent") return c.accent;
    if (tone === "bone") return c.bone2;
    if (tone === "mute") return c.rule;
    return c.accentLine;
  }

  function fillFor(tone) {
    var c = colours();
    if (tone === "accent") return c.accentSoft;
    if (tone === "bone") return "rgba(240,234,221,0.08)";
    if (tone === "mute") return "rgba(240,234,221,0.06)";
    return "rgba(0,0,0,0.28)";
  }

  function inkFor(tone) {
    var c = colours();
    if (tone === "mute") return c.bone2;
    if (tone === "line") return c.bone;
    return c.bone;
  }

  function ensureCanvasMetrics(canvas, ctx) {
    var rect = canvas.getBoundingClientRect();
    var width = Math.max(1, Math.round(rect.width || canvas.clientWidth || 320));
    var height = Math.max(1, Math.round(rect.height || 180));
    var dpr = window.devicePixelRatio || 1;
    var targetW = Math.round(width * dpr);
    var targetH = Math.round(height * dpr);
    if (canvas.width !== targetW || canvas.height !== targetH) {
      canvas.width = targetW;
      canvas.height = targetH;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, width, height);
    return { width: width, height: height };
  }

  var lastTree = null;
  var lastNote = "";

  function drawTree(tree, note) {
    lastTree = tree || null;
    lastNote = note || "";
    var canvas = refs.treeCanvas;
    if (!canvas || typeof canvas.getContext !== "function") return;
    var ctx = canvas.getContext("2d");
    if (!ctx) return;

    var box = ensureCanvasMetrics(canvas, ctx);
    var width = box.width;
    var height = box.height;
    var c = colours();

    if (!tree) {
      drawCenteredMessage(
        ctx,
        width,
        height,
        state.expression.trim() ? "structure incomplete" : "no expression yet"
      );
      return;
    }

    var total = countNodes(tree);
    if (total > MAX_TREE_TOKENS) {
      drawCenteredMessage(ctx, width, height, total + " nodes — too long to map");
      return;
    }

    ctx.font = "11px " + monoStack();
    measureNode(ctx, tree);
    placeNode(tree, 0, 0, 0);

    var depth = maxDepth(tree);
    var treeW = tree.width;
    var treeH = (depth + 1) * ROW_H - (ROW_H - NODE_H);
    var pad = 8;
    var scale = Math.min(1, (width - pad * 2) / Math.max(1, treeW));
    var offsetX = (width - treeW * scale) / 2;
    var offsetY = Math.max(pad, (height - treeH * scale) / 2);

    ctx.save();
    ctx.translate(offsetX, offsetY);
    ctx.scale(scale, scale);

    /* Edges first so nodes sit on top of them. */
    ctx.strokeStyle = c.rule;
    ctx.lineWidth = 1;
    (function drawEdges(node) {
      node.kids.forEach(function (child) {
        var midY = (node.top + NODE_H + child.top) / 2;
        ctx.beginPath();
        ctx.moveTo(node.centerX, node.top + NODE_H);
        ctx.lineTo(node.centerX, midY);
        ctx.lineTo(child.centerX, midY);
        ctx.lineTo(child.centerX, child.top);
        ctx.stroke();
        drawEdges(child);
      });
    })(tree);

    (function drawNodes(node) {
      var tone = toneFor(node);
      roundRect(ctx, node.left, node.top, node.width, NODE_H, 4);
      ctx.fillStyle = fillFor(tone);
      ctx.fill();
      ctx.strokeStyle = toneColor(tone);
      ctx.globalAlpha = tone === "line" ? 0.85 : 0.6;
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.fillStyle = inkFor(tone);
      ctx.font = "11px " + monoStack();
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(node.label, node.left + node.width / 2, node.top + NODE_H / 2 + 0.5);
      node.kids.forEach(drawNodes);
    })(tree);

    ctx.restore();
  }

  function treeNote(structure) {
    if (refs.treeNote) {
      if (!structure || !structure.ok) {
        refs.treeNote.textContent = (structure && structure.error) || "structure incomplete";
        refs.treeNote.classList.remove("is-accent");
      } else if (structure.tree) {
        var nodes = countNodes(structure.tree);
        refs.treeNote.textContent = nodes + (nodes === 1 ? " node" : " nodes") + " · depth " + (maxDepth(structure.tree) + 1);
        refs.treeNote.classList.add("is-accent");
      } else {
        refs.treeNote.textContent = "waiting for input";
        refs.treeNote.classList.remove("is-accent");
      }
    }
    return refs.treeNote ? refs.treeNote.textContent : "";
  }

  function redraw() {
    colourCache = null;
    if (refs.treeCanvas) drawTree(lastTree, lastNote);
  }

  /* ====================================================================== */
  /* 5. Wiring                                                                */
  /* ====================================================================== */
  function wire() {
    if (refs.form) {
      refs.form.addEventListener("submit", function (event) {
        event.preventDefault();
        commit();
      });
    }

    if (refs.input) {
      refs.input.addEventListener("input", function () {
        handleInput();
      });
      refs.input.addEventListener("keydown", function (event) {
        if (event.key === "Enter") {
          event.preventDefault();
          commit();
        } else if (event.key === "Escape") {
          event.preventDefault();
          clearAll();
        }
      });
    }

    if (refs.keypad) {
      refs.keypad.addEventListener("click", function (event) {
        var button = event.target && event.target.closest ? event.target.closest("button") : null;
        if (!button) return;
        var insert = button.getAttribute("data-insert");
        var action = button.getAttribute("data-action");
        if (insert !== null) insertText(insert);
        else if (action === "clear") clearAll();
        else if (action === "backspace") backspace();
        else if (action === "sign") toggleSign();
        else if (action === "equals") commit();
      });
    }

    for (var i = 0; i < refs.angleButtons.length; i += 1) {
      refs.angleButtons[i].addEventListener("click", function (event) {
        setAngle(event.currentTarget.getAttribute("data-angle"));
      });
    }

    if (refs.history) {
      refs.history.addEventListener("click", function (event) {
        var button = event.target && event.target.closest ? event.target.closest("[data-index]") : null;
        if (!button) return;
        var entry = state.history[Number(button.getAttribute("data-index"))];
        if (!entry) return;
        if (entry.angle === "rad" && state.degrees) setAngle("rad");
        if (entry.angle === "deg" && !state.degrees) setAngle("deg");
        setExpression(entry.expression);
        pushHistory(
          Object.assign({}, entry, { at: Date.now() })
        );
        announce("Reused " + entry.expression);
      });
    }

    if (refs.historyClear) {
      refs.historyClear.addEventListener("click", function () {
        state.history = [];
        saveHistory();
        renderHistory();
        announce("History cleared");
      });
    }

    /* Keyboard support beyond the field: Escape clears from anywhere, and
       calculator symbols typed while a keypad key has focus go to the field.
       Digits are deliberately left alone outside the input because 1/2/3 are
       the mode shortcuts owned by app.js. */
    document.addEventListener("keydown", function (event) {
      var target = event.target;
      var typing =
        target && (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName || ""));
      if (event.key === "Escape" && !typing) {
        event.preventDefault();
        clearAll();
        return;
      }
      if (typing || event.ctrlKey || event.metaKey || event.altKey) return;
      if (/^[+\-*/^().,%]$/.test(event.key) || /^[a-zA-Z]$/.test(event.key)) {
        event.preventDefault();
        insertText(event.key);
      }
    });

    if (typeof window.ResizeObserver === "function" && refs.treeCanvas) {
      var observer = new window.ResizeObserver(function () {
        redraw();
      });
      var frame = refs.treeCanvas.parentNode;
      if (frame) observer.observe(frame);
    } else {
      window.addEventListener("resize", redraw);
    }

    var start = "";
    try {
      start = window.localStorage.getItem("numera.scientific.last") || "";
    } catch (error) {
      start = "";
    }
    if (refs.input) {
      refs.input.value = /^[\d\s+\-*/^().,%a-zA-Z]*$/.test(start) ? start : "";
      state.expression = refs.input.value;
      handleInput({ server: false });
      var fine = window.matchMedia && window.matchMedia("(hover: hover) and (pointer: fine)").matches;
      if (fine) refs.input.focus({ preventScroll: true });
    } else {
      handleInput({ server: false });
    }
  }

  function rememberLast() {
    try {
      window.localStorage.setItem("numera.scientific.last", state.expression);
    } catch (error) {
      /* ignore */
    }
  }

  ready(function () {
    collect();
    state.history = loadHistory();
    renderHistory();
    wire();
    drawTree(null, "");
    window.addEventListener("pagehide", rememberLast);
    window.addEventListener("beforeunload", rememberLast);
  });

  /* Exposed for the standalone preview / console debugging. */
  window.NumeraScientific = {
    calculate: calculate,
    tokenize: tokenize,
    normalise: normalise,
    formatNumber: formatNumber,
    structure: parseStructure,
    state: state
  };
})();

