/* ==========================================================================
   Numera — date panel
   --------------------------------------------------------------------------
   Same two-layer shape as static/js/scientific.js:

   1. THE MIRROR  re-implements the part of calculators/dates.py the panel uses
      (difference + add/subtract) with the same field names, so the readout
      updates on every input change and still works if POST /api/date fails:

          { ok, operation, error, start, start_display, end, end_display,
            result, result_display, years, months, days, display, total_days,
            weekdays, weekend_days, days_moved, clamped, ... }

      Calendar maths is done on integer day numbers (no local-timezone Dates),
      using the same months-then-days breakdown and month-end clamping as the
      Python engine.

   2. THE PANEL   inner tabs (Difference / Add–subtract), date inputs, presets,
      a large day-count readout, a y/m/d breakdown, a recent-answers history in
      localStorage (capped at 20) and two canvas visualisations that are drawn
      from the real answer:
        • span bar      month-by-month proportion of the interval
        • weekday chart how many Mondays … Sundays the interval contains,
                        with the start and end weekday marked
   ========================================================================== */
(function () {
  "use strict";

  var HISTORY_KEY = "numera.history.date";
  var HISTORY_MAX = 20;
  var DEBOUNCE_MS = 180;
  var MAX_MONTH_SEGMENTS = 60;

  var DAY_MS = 86400000;
  var WEEKDAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
  var WEEKDAY_SHORT = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  var WEEKDAY_LETTERS = ["M", "T", "W", "T", "F", "S", "S"];
  var MONTH_NAMES = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];
  var MONTH_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  var UNITS = ["days", "weeks", "months", "years"];
  var BUSINESS_UNITS = ["days", "weeks"];
  var MAX_AMOUNT = 1000000;

  /* ====================================================================== */
  /* 1. Civil-date integer maths (timezone-free)                              */
  /* ====================================================================== */
  function pad(value, width) {
    var text = String(Math.abs(value));
    while (text.length < width) text = "0" + text;
    return (value < 0 ? "-" : "") + text;
  }

  function isLeapYear(year) {
    return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  }

  function daysInMonth(year, month) {
    if (month === 2) return isLeapYear(year) ? 29 : 28;
    if (month === 4 || month === 6 || month === 9 || month === 11) return 30;
    return 31;
  }

  /* Howard Hinnant's days<->civil algorithms: exact for every year, no DST. */
  function daysFromCivil(year, month, day) {
    var y = month <= 2 ? year - 1 : year;
    var era = Math.floor((y >= 0 ? y : y - 399) / 400);
    var yoe = y - era * 400;
    var doy = Math.floor((153 * (month + (month > 2 ? -3 : 9)) + 2) / 5) + day - 1;
    var doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
    return era * 146097 + doe - 719468;
  }

  function civilFromDays(days) {
    var z = days + 719468;
    var era = Math.floor((z >= 0 ? z : z - 146096) / 146097);
    var doe = z - era * 146097;
    var yoe = Math.floor(
      (doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365
    );
    var year = yoe + era * 400;
    var doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
    var mp = Math.floor((5 * doy + 2) / 153);
    var day = doy - Math.floor((153 * mp + 2) / 5) + 1;
    var month = mp + (mp < 10 ? 3 : -9);
    return { year: year + (month <= 2 ? 1 : 0), month: month, day: day };
  }

  /* 1970-01-01 was a Thursday, i.e. weekday index 3 with Monday = 0. */
  function weekdayIndex(days) {
    return (((days + 3) % 7) + 7) % 7;
  }

  function parseISO(text) {
    if (typeof text !== "string") return null;
    var match = /^\s*(\d{4})-(\d{1,2})-(\d{1,2})/.exec(text);
    if (!match) return null;
    var year = Number(match[1]);
    var month = Number(match[2]);
    var day = Number(match[3]);
    if (!(year >= 1 && year <= 9999)) return null;
    if (!(month >= 1 && month <= 12)) return null;
    if (!(day >= 1 && day <= daysInMonth(year, month))) return null;
    return { year: year, month: month, day: day };
  }

  function isoOf(parts) {
    return pad(parts.year, 4) + "-" + pad(parts.month, 2) + "-" + pad(parts.day, 2);
  }

  function dayNumberOf(parts) {
    return daysFromCivil(parts.year, parts.month, parts.day);
  }

  function isoFromDayNumber(days) {
    return isoOf(civilFromDays(days));
  }

  function weekdayOfIso(iso) {
    var parts = parseISO(iso);
    return parts ? weekdayIndex(dayNumberOf(parts)) : 0;
  }

  function displayOfIso(iso) {
    var parts = parseISO(iso);
    if (!parts) return "";
    return (
      WEEKDAY_NAMES[weekdayIndex(dayNumberOf(parts))] +
      ", " + parts.day + " " + MONTH_NAMES[parts.month - 1] + " " + parts.year
    );
  }

  function isoWeekOfIso(iso) {
    var parts = parseISO(iso);
    if (!parts) return "";
    var days = dayNumberOf(parts);
    var weekday = weekdayIndex(days); /* Monday = 0 */
    var thursday = days - weekday + 3;
    var civil = civilFromDays(thursday);
    var jan1 = daysFromCivil(civil.year, 1, 1);
    var week = Math.floor((thursday - jan1) / 7) + 1;
    return civil.year + "-W" + pad(week, 2) + "-" + (weekday + 1);
  }

  function dayOfYearOfIso(iso) {
    var parts = parseISO(iso);
    if (!parts) return 0;
    return dayNumberOf(parts) - daysFromCivil(parts.year, 1, 1) + 1;
  }

  function addDaysToNumber(days, amount) {
    return days + amount;
  }

  function shiftMonthNumber(days, months) {
    var civil = civilFromDays(days);
    var total = civil.year * 12 + (civil.month - 1) + months;
    var year = Math.floor(total / 12);
    var month = total - year * 12 + 1;
    var day = Math.min(civil.day, daysInMonth(year, month));
    return { days: daysFromCivil(year, month, day), clamped: day !== civil.day };
  }

  function addBusinessDays(days, amount) {
    var current = days;
    var remaining = amount;
    if (!remaining) return current;
    var step = remaining > 0 ? 1 : -1;
    while (weekdayIndex(current) >= 5 && remaining) {
      current += step;
      if (weekdayIndex(current) < 5) remaining -= step;
    }
    if (!remaining) return current;
    var weeks = Math.floor(Math.abs(remaining) / 5);
    var remainder = Math.abs(remaining) % 5;
    if (weeks) {
      current += step * weeks * 7;
      remaining = step * remainder;
    }
    while (remaining) {
      current += step;
      if (weekdayIndex(current) < 5) remaining -= step;
    }
    return current;
  }

  function ymdBetween(firstDays, lastDays) {
    var from = Math.min(firstDays, lastDays);
    var to = Math.max(firstDays, lastDays);
    var a = civilFromDays(from);
    var b = civilFromDays(to);
    var months = (b.year - a.year) * 12 + (b.month - a.month);
    if (months < 0) months = 0;
    var anchor = shiftMonthNumber(from, months).days;
    if (anchor > to) {
      months -= 1;
      anchor = shiftMonthNumber(from, months).days;
    }
    var days = to - anchor;
    var years = Math.floor(months / 12);
    return { years: years, months: months - years * 12, days: days };
  }

  function countWeekdays(firstDays, lastDays) {
    var from = Math.min(firstDays, lastDays);
    var to = Math.max(firstDays, lastDays);
    var span = to - from;
    if (span <= 0) return 0;
    var weeks = Math.floor(span / 7);
    var remainder = span % 7;
    var total = weeks * 5;
    var start = weekdayIndex(from);
    for (var offset = 0; offset < remainder; offset += 1) {
      if ((start + offset) % 7 < 5) total += 1;
    }
    return total;
  }

  function plural(value, unit) {
    return value + " " + unit + (value === 1 ? "" : "s");
  }

  function formatYmd(years, months, days) {
    var parts = [];
    if (years) parts.push(plural(years, "year"));
    if (months) parts.push(plural(months, "month"));
    if (days) parts.push(plural(days, "day"));
    return parts.length ? parts.join(" ") : "same day";
  }

  function directionOf(fromIso, toIso) {
    var from = dayNumberOf(parseISO(fromIso));
    var to = dayNumberOf(parseISO(toIso));
    if (to > from) return "future";
    if (to < from) return "past";
    return "same";
  }

  function errorResult(operation, message) {
    return { ok: false, operation: operation, error: message };
  }

  /* ====================================================================== */
  /* 2. The mirror: difference + add/subtract                                 */
  /* ====================================================================== */
  function difference(start, end) {
    var startParts = parseISO(start);
    var endParts = parseISO(end);
    if (!startParts) return errorResult("difference", "Pick a valid start date");
    if (!endParts) return errorResult("difference", "Pick a valid end date");

    var first = dayNumberOf(startParts);
    var last = dayNumberOf(endParts);
    var ymd = ymdBetween(first, last);
    var total = Math.abs(last - first);
    var weekdays = countWeekdays(first, last);
    var sign = last > first ? 1 : last < first ? -1 : 0;
    var startIso = isoOf(startParts);
    var endIso = isoOf(endParts);

    return {
      ok: true,
      operation: "difference",
      error: null,
      start: startIso,
      start_display: displayOfIso(startIso),
      start_weekday: WEEKDAY_NAMES[weekdayOfIso(startIso)],
      end: endIso,
      end_display: displayOfIso(endIso),
      end_weekday: WEEKDAY_NAMES[weekdayOfIso(endIso)],
      years: ymd.years,
      months: ymd.months,
      days: ymd.days,
      display: formatYmd(ymd.years, ymd.months, ymd.days),
      total_days: total,
      signed_days: last - first,
      weeks: Math.floor(total / 7),
      days_remainder: total % 7,
      total_weeks: Math.round((total / 7) * 10000) / 10000,
      weekdays: weekdays,
      weekend_days: total - weekdays,
      sign: sign,
      direction: directionOf(startIso, endIso),
      is_future: sign > 0,
      is_past: sign < 0,
      note: "Weekdays/weekend days count from start up to (not including) end."
    };
  }

  function shift(operation, dateText, amountText, unitText, business) {
    var subtract = operation === "subtract";
    var parts = parseISO(dateText);
    if (!parts) return errorResult(operation, "Pick a valid date");

    var amount = Number(amountText);
    if (amountText === "" || amountText === null || !isFinite(amount) || amount !== Math.floor(amount)) {
      return errorResult(operation, "Enter a whole number of units");
    }
    if (Math.abs(amount) > MAX_AMOUNT) {
      return errorResult(operation, "That amount is too large");
    }

    var unit = String(unitText || "days").toLowerCase();
    if (UNITS.indexOf(unit) === -1) return errorResult(operation, "Choose days, weeks, months or years");
    var useBusiness = business === true || business === "true";
    if (useBusiness && BUSINESS_UNITS.indexOf(unit) === -1) {
      return errorResult(operation, "Business-day counting only works with days or weeks");
    }

    var signed = subtract ? -amount : amount;
    var startDays = dayNumberOf(parts);
    var resultDays;
    var clamped = false;

    if (unit === "days" || unit === "weeks") {
      var dayCount = unit === "days" ? signed : signed * 7;
      resultDays = useBusiness ? addBusinessDays(startDays, dayCount) : addDaysToNumber(startDays, dayCount);
    } else {
      var months = unit === "years" ? signed * 12 : signed;
      var moved = shiftMonthNumber(startDays, months);
      resultDays = moved.days;
      clamped = moved.clamped;
    }

    if (resultDays < daysFromCivil(1, 1, 1) || resultDays > daysFromCivil(9999, 12, 31)) {
      return errorResult(operation, "The result date is outside the supported range");
    }

    var startIso = isoOf(parts);
    var resultIso = isoFromDayNumber(resultDays);
    var note = clamped
      ? "Month-end clamp applied: day " + parts.day + " does not exist in " +
        MONTH_NAMES[civilFromDays(resultDays).month - 1] + " " + civilFromDays(resultDays).year + "."
      : null;

    return {
      ok: true,
      operation: subtract ? "subtract" : "add",
      error: null,
      start: startIso,
      start_display: displayOfIso(startIso),
      start_weekday: WEEKDAY_NAMES[weekdayOfIso(startIso)],
      result: resultIso,
      result_display: displayOfIso(resultIso),
      result_weekday: WEEKDAY_NAMES[weekdayOfIso(resultIso)],
      amount: amount,
      signed_amount: signed,
      unit: unit,
      business_days: useBusiness,
      days_moved: resultDays - startDays,
      direction: directionOf(startIso, resultIso),
      clamped: clamped,
      note: note,
      day_of_year: dayOfYearOfIso(resultIso),
      leap_year: isLeapYear(civilFromDays(resultDays).year),
      iso_week: isoWeekOfIso(resultIso)
    };
  }

  function calculateLocal(inputs) {
    if (inputs.mode === "shift") {
      return shift(
        inputs.direction === "subtract" ? "subtract" : "add",
        inputs.date,
        inputs.amount,
        inputs.unit,
        inputs.business
      );
    }
    return difference(inputs.start, inputs.end);
  }

  /* ====================================================================== */
  /* 3. Panel state                                                          */
  /* ====================================================================== */
  var shell = window.Numera || null;

  function ready(fn) {
    if (shell && typeof shell.ready === "function") shell.ready(fn);
    else if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else fn();
  }

  function announce(message) {
    if (shell && typeof shell.announce === "function") shell.announce(message);
  }

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = String(text);
    return node;
  }

  function groupDigits(value) {
    var text = String(Math.abs(value));
    var out = "";
    for (var i = 0; i < text.length; i += 1) {
      var fromEnd = text.length - i;
      out += text.charAt(i);
      if (fromEnd > 1 && (fromEnd - 1) % 3 === 0) out += ",";
    }
    return (value < 0 ? "−" : "") + out;
  }

  function todayIso() {
    var now = new Date();
    return isoOf({ year: now.getFullYear(), month: now.getMonth() + 1, day: now.getDate() });
  }

  function todayDayNumber() {
    return dayNumberOf(parseISO(todayIso()));
  }

  function lastDayOfMonthIso(iso) {
    var parts = parseISO(iso) || parseISO(todayIso());
    return isoOf({ year: parts.year, month: parts.month, day: daysInMonth(parts.year, parts.month) });
  }

  function formatTime(stamp) {
    var date = new Date(stamp);
    if (isNaN(date.getTime())) return "";
    return pad(date.getHours(), 2) + ":" + pad(date.getMinutes(), 2);
  }

  var state = {
    mode: "difference",
    direction: "add",
    business: false,
    result: null,
    history: [],
    sequence: 0,
    timer: 0,
    fromIso: "",
    toIso: ""
  };

  var refs = {};

  function collect() {
    refs.subtabs = document.querySelectorAll("[data-subtab]");
    refs.subpanels = document.querySelectorAll("[data-subpanel]");
    refs.start = document.querySelector('[data-input="start"]');
    refs.end = document.querySelector('[data-input="end"]');
    refs.date = document.querySelector('[data-input="date"]');
    refs.amount = document.querySelector('[data-input="amount"]');
    refs.unit = document.querySelector('[data-input="unit"]');
    refs.business = document.querySelector("[data-business]");
    refs.directionButtons = document.querySelectorAll("[data-direction]");
    refs.presets = document.querySelectorAll("[data-preset]");
    refs.dayCount = document.querySelector("[data-day-count]");
    refs.dayUnit = document.querySelector("[data-day-unit]");
    refs.caption = document.querySelector("[data-result-caption]");
    refs.badge = document.querySelector("[data-result-badge]");
    refs.engineChip = document.querySelector("[data-engine-chip]");
    refs.breakdown = document.querySelector("[data-breakdown]");
    refs.spanCanvas = document.querySelector("[data-span-canvas]");
    refs.spanNote = document.querySelector("[data-span-note]");
    refs.weekdayCanvas = document.querySelector("[data-weekday-canvas]");
    refs.weekdayNote = document.querySelector("[data-weekday-note]");
    refs.history = document.querySelector("[data-history]");
    refs.historyEmpty = document.querySelector("[data-history-empty]");
    refs.historyCount = document.querySelector("[data-history-count]");
    refs.historyClear = document.querySelector("[data-history-clear]");
  }

  /* ------------------------------------------------------------- history -- */
  function loadHistory() {
    var raw = null;
    try {
      raw = window.localStorage.getItem(HISTORY_KEY);
    } catch (error) {
      raw = null;
    }
    if (!raw) return [];
    try {
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed
        .filter(function (entry) {
          return entry && typeof entry.label === "string" && entry.inputs;
        })
        .slice(0, HISTORY_MAX);
    } catch (error) {
      return [];
    }
  }

  function saveHistory() {
    try {
      window.localStorage.setItem(HISTORY_KEY, JSON.stringify(state.history));
    } catch (error) {
      /* private mode: session list still works */
    }
  }

  function pushHistory(entry) {
    state.history = state.history.filter(function (item) {
      return item.label !== entry.label || item.mode !== entry.mode;
    });
    state.history.unshift(entry);
    if (state.history.length > HISTORY_MAX) state.history.length = HISTORY_MAX;
    saveHistory();
    renderHistory();
  }

  function renderHistory() {
    if (!refs.history) return;
    while (refs.history.firstChild) refs.history.removeChild(refs.history.firstChild);

    state.history.forEach(function (entry, index) {
      var item = el("li");
      var button = el("button", "history__btn");
      button.type = "button";
      button.setAttribute("data-index", String(index));
      button.setAttribute("aria-label", "Restore " + entry.label + ", " + entry.value);
      button.appendChild(el("span", "history__expression", entry.label));
      button.appendChild(el("span", "history__result", entry.value));
      button.appendChild(
        el("span", "history__meta", (entry.mode === "shift" ? "add / subtract" : "difference") + " · " + formatTime(entry.at))
      );
      item.appendChild(button);
      refs.history.appendChild(item);
    });

    if (refs.historyCount) refs.historyCount.textContent = state.history.length + " / " + HISTORY_MAX;
    if (refs.historyEmpty) {
      if (state.history.length) refs.historyEmpty.classList.add("is-hidden");
      else refs.historyEmpty.classList.remove("is-hidden");
    }
  }

  /* --------------------------------------------------------------- inputs -- */
  function readInputs() {
    return {
      mode: state.mode,
      start: refs.start ? refs.start.value : "",
      end: refs.end ? refs.end.value : "",
      date: refs.date ? refs.date.value : "",
      amount: refs.amount ? refs.amount.value : "",
      unit: refs.unit ? refs.unit.value : "days",
      direction: state.direction,
      business: state.business
    };
  }

  function setInputValues(inputs) {
    if (!inputs) return;
    var map = [
      [refs.start, inputs.start],
      [refs.end, inputs.end],
      [refs.date, inputs.date],
      [refs.amount, inputs.amount],
      [refs.unit, inputs.unit]
    ];
    map.forEach(function (pair) {
      if (pair[0] && pair[1] !== undefined && pair[1] !== null) pair[0].value = pair[1];
    });
    if (inputs.direction) setDirection(inputs.direction, true);
    if (inputs.business !== undefined) setBusiness(inputs.business === true, true);
  }

  function setDirection(direction, quiet) {
    state.direction = direction === "subtract" ? "subtract" : "add";
    for (var i = 0; i < refs.directionButtons.length; i += 1) {
      var button = refs.directionButtons[i];
      var active = button.getAttribute("data-direction") === state.direction;
      button.setAttribute("aria-pressed", active ? "true" : "false");
    }
    if (!quiet) refresh();
  }

  function setBusiness(on, quiet) {
    state.business = on === true;
    if (refs.business) refs.business.setAttribute("aria-pressed", state.business ? "true" : "false");
    if (!quiet) refresh();
  }

  /* ---------------------------------------------------------------- paint -- */
  function setBadge(text, tone) {
    if (refs.badge) {
      refs.badge.textContent = text;
      refs.badge.classList.remove("is-accent", "is-warn");
      if (tone === "api") refs.badge.classList.add("is-accent");
      if (tone === "error") refs.badge.classList.add("is-warn");
    }
    if (refs.engineChip) {
      refs.engineChip.textContent = tone === "api" ? "api verified" : "local engine";
    }
  }

  function endIsoOf(result) {
    if (!result) return "";
    return result.end || result.result || "";
  }

  function primaryReadout(result, inputs) {
    if (!result || !result.ok) {
      return {
        value: (result && result.error) || "Pick two dates",
        unit: "",
        caption: "",
        error: true
      };
    }
    if (result.operation === "difference") {
      var sign = result.direction === "future" ? "ahead" : result.direction === "past" ? "behind" : "apart";
      return {
        value: groupDigits(result.total_days),
        unit: result.total_days === 1 ? "day " + sign : "days " + sign,
        caption: result.display + " — " + result.start_display + " → " + result.end_display,
        error: false
      };
    }
    var moved = result.days_moved;
    var magnitude = Math.abs(moved);
    var tone = moved > 0 ? "later" : moved < 0 ? "earlier" : "on the same day";
    return {
      value: groupDigits(magnitude),
      unit: moved === 0 ? "days — no movement" : magnitude === 1 ? "day " + tone : "days " + tone,
      caption: result.start_display + " " + (result.operation === "subtract" ? "−" : "+") + " " +
        result.amount + " " + result.unit + " = " + result.result_display,
      error: false
    };
  }

  function addRow(term, value, accent) {
    if (!refs.breakdown) return;
    var row = el("div");
    row.appendChild(el("dt", null, term));
    var dd = el("dd", accent ? "is-accent" : null, value);
    row.appendChild(dd);
    refs.breakdown.appendChild(row);
  }

  function renderBreakdown(result) {
    if (!refs.breakdown) return;
    while (refs.breakdown.firstChild) refs.breakdown.removeChild(refs.breakdown.firstChild);
    if (!result || !result.ok) {
      addRow("Status", "waiting for two valid dates");
      return;
    }
    if (result.operation === "difference") {
      addRow("Years", String(result.years));
      addRow("Months", String(result.months));
      addRow("Days", String(result.days));
      addRow("Total days", groupDigits(result.total_days));
      addRow("Weeks", result.weeks + " w " + result.days_remainder + " d");
      addRow("Weekdays", groupDigits(result.weekdays));
      addRow("Weekend days", groupDigits(result.weekend_days));
      addRow("Direction", result.direction);
      return;
    }
    addRow("Shift", result.amount + " " + result.unit + (result.operation === "subtract" ? " back" : " forward"));
    addRow("Result", result.result, true);
    addRow("Result weekday", result.result_weekday || WEEKDAY_NAMES[weekdayOfIso(result.result)]);
    addRow("Days moved", (result.days_moved > 0 ? "+" : "") + groupDigits(result.days_moved));
    addRow("ISO week", result.iso_week || isoWeekOfIso(result.result));
    addRow("Day of year", String(result.day_of_year || dayOfYearOfIso(result.result)));
    addRow("Business days", result.business_days ? "yes (Mon–Fri)" : "no");
    if (result.clamped) addRow("Month-end", "clamped to the last day");
  }

  /* ====================================================================== */
  /* 4. Canvas visualisations                                                */
  /* ====================================================================== */
  var colourCache = null;

  function monoStack() {
    return 'ui-monospace, "SFMono-Regular", "Cascadia Mono", Menlo, Consolas, monospace';
  }

  function colours() {
    if (colourCache) return colourCache;
    var style = window.getComputedStyle(document.body);
    function read(name, fallback) {
      var value = style.getPropertyValue(name);
      return value && value.trim() ? value.trim() : fallback;
    }
    colourCache = {
      accent: read("--accent", "#b79bf6"),
      accentLine: read("--accent-line", "rgba(183,155,246,0.42)"),
      accentSoft: read("--accent-soft", "rgba(183,155,246,0.14)"),
      bone: read("--bone", "#f0eadd"),
      bone2: read("--bone-2", "#c3bdaf"),
      bone3: read("--bone-3", "#968f84"),
      rule: read("--rule", "rgba(240,234,221,0.14)"),
      ruleSoft: read("--rule-soft", "rgba(240,234,221,0.075)")
    };
    return colourCache;
  }

  function prepare(canvas) {
    if (!canvas || typeof canvas.getContext !== "function") return null;
    var ctx = canvas.getContext("2d");
    if (!ctx) return null;
    var rect = canvas.getBoundingClientRect();
    var width = Math.max(1, Math.round(rect.width || canvas.clientWidth || 320));
    var height = Math.max(1, Math.round(rect.height || 168));
    var dpr = window.devicePixelRatio || 1;
    var targetW = Math.round(width * dpr);
    var targetH = Math.round(height * dpr);
    if (canvas.width !== targetW || canvas.height !== targetH) {
      canvas.width = targetW;
      canvas.height = targetH;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, width, height);
    return { ctx: ctx, width: width, height: height };
  }

  function message(ctx, width, height, text) {
    ctx.fillStyle = colours().bone3;
    ctx.font = "12px " + monoStack();
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(text, width / 2, height / 2);
  }

  /* Month segments that cover the half-open interval [from, to). */
  function monthSegments(fromDays, toDays) {
    var segments = [];
    var start = civilFromDays(fromDays);
    var end = civilFromDays(Math.max(fromDays, toDays - 1));
    var year = start.year;
    var month = start.month;
    while (year < end.year || (year === end.year && month <= end.month)) {
      var firstOfMonth = daysFromCivil(year, month, 1);
      var lastOfMonth = daysFromCivil(year, month, daysInMonth(year, month));
      var from = Math.max(fromDays, firstOfMonth);
      var to = Math.min(toDays - 1, lastOfMonth);
      var count = to - from + 1;
      if (count > 0) segments.push({ year: year, month: month, days: count });
      month += 1;
      if (month > 12) {
        month = 1;
        year += 1;
      }
