    return segments;
  }

  function aggregateByYear(segments) {
    var out = [];
    segments.forEach(function (segment) {
      var last = out[out.length - 1];
      if (last && last.year === segment.year) last.days += segment.days;
      else out.push({ year: segment.year, days: segment.days });
    });
    return out;
  }

  function drawSpan(fromIso, toIso) {
    var box = prepare(refs.spanCanvas);
    if (refs.spanNote) refs.spanNote.textContent = "—";
    if (!box) return;
    var ctx = box.ctx;
    var width = box.width;
    var height = box.height;
    var c = colours();

    var fromParts = parseISO(fromIso);
    var toParts = parseISO(toIso);
    if (!fromParts || !toParts) {
      message(ctx, width, height, "no span yet");
      return;
    }

    var fromDays = dayNumberOf(fromParts);
    var toDays = dayNumberOf(toParts);
    var first = Math.min(fromDays, toDays);
    var last = Math.max(fromDays, toDays);
    var total = last - first;
    var reversed = toDays < fromDays;

    if (refs.spanNote) {
      refs.spanNote.textContent = total === 0
        ? "same day"
        : groupDigits(total) + " days · " + (reversed ? "backwards" : "forwards");
      refs.spanNote.classList.add("is-accent");
    }

    if (total === 0) {
      var centre = width / 2;
      ctx.strokeStyle = c.accent;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(centre, height / 2 - 26);
      ctx.lineTo(centre, height / 2 + 26);
      ctx.stroke();
      ctx.fillStyle = c.accent;
      ctx.beginPath();
      ctx.arc(centre, height / 2 - 30, 3.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = c.bone2;
      ctx.font = "11px " + monoStack();
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      ctx.fillText(displayOfIso(fromIso), centre, height / 2 + 34);
      return;
    }

    var segments = monthSegments(first, last);
    var byYear = segments.length > MAX_MONTH_SEGMENTS;
    if (byYear) segments = aggregateByYear(segments);

    var pad = 10;
    var barW = width - pad * 2;
    var barH = 46;
    var contentH = 18 + 10 + barH + 26;
    var top = Math.max(8, Math.round((height - contentH) / 2));
    var barTop = top + 28;

    ctx.textBaseline = "alphabetic";

    /* baseline under the bar */
    ctx.strokeStyle = c.ruleSoft;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pad, barTop + barH + 0.5);
    ctx.lineTo(width - pad, barTop + barH + 0.5);
    ctx.stroke();

    var x = pad;
    var lastYear = null;
    segments.forEach(function (segment, index) {
      var segmentW = (segment.days / total) * barW;
      ctx.fillStyle = index % 2 === 0 ? c.accentSoft : "rgba(0,0,0,0.22)";
      ctx.fillRect(x, barTop, Math.max(segmentW, 0.6), barH);
      ctx.strokeStyle = c.ruleSoft;
      ctx.beginPath();
      ctx.moveTo(x + 0.5, barTop);
      ctx.lineTo(x + 0.5, barTop + barH);
      ctx.stroke();

      if (segment.year !== lastYear) {
        ctx.fillStyle = c.bone3;
        ctx.font = "10px " + monoStack();
        ctx.textAlign = "left";
        ctx.fillText(String(segment.year), x + 2, barTop - 8);
        lastYear = segment.year;
      }

      if (segmentW > 26) {
        ctx.fillStyle = c.bone2;
        ctx.font = "10px " + monoStack();
        ctx.textAlign = "center";
        var label = byYear ? String(segment.year) : MONTH_SHORT[segment.month - 1];
        ctx.fillText(label, x + segmentW / 2, barTop + barH / 2 + 3.5);
      }
      x += segmentW;
    });

    /* end caps + dates under the ends */
    ctx.strokeStyle = c.accent;
    ctx.lineWidth = 2;
    [pad, width - pad].forEach(function (edge) {
      ctx.beginPath();
      ctx.moveTo(edge, barTop - 4);
      ctx.lineTo(edge, barTop + barH + 4);
      ctx.stroke();
    });

    ctx.fillStyle = c.bone2;
    ctx.font = "10px " + monoStack();
    ctx.textAlign = "left";
    ctx.fillText(fromIso, pad, barTop + barH + 18);
    ctx.textAlign = "right";
    ctx.fillText(toIso, width - pad, barTop + barH + 18);

    if (reversed) {
      ctx.fillStyle = c.bone3;
      ctx.textAlign = "center";
      ctx.fillText("arrows point back to the start date", width / 2, barTop + barH + 34);
    }
  }

  function drawWeekdays(fromIso, toIso) {
    var box = prepare(refs.weekdayCanvas);
    if (!box) return;
    var ctx = box.ctx;
    var width = box.width;
    var height = box.height;
    var c = colours();
    var counts = [0, 0, 0, 0, 0, 0, 0];

    var fromParts = parseISO(fromIso);
    var toParts = parseISO(toIso);
    if (!fromParts || !toParts) {
      message(ctx, width, height, "no interval yet");
      if (refs.weekdayNote) refs.weekdayNote.textContent = "—";
      return;
    }

    var fromDays = dayNumberOf(fromParts);
    var toDays = dayNumberOf(toParts);
    var first = Math.min(fromDays, toDays);
    var last = Math.max(fromDays, toDays);
    var total = last - first;
    var single = total === 0;

    if (single) {
      counts[weekdayIndex(first)] = 1;
    } else {
      for (var day = first; day < last; day += 1) counts[weekdayIndex(day)] += 1;
    }

    var weekdayTotal = counts[0] + counts[1] + counts[2] + counts[3] + counts[4];
    var weekendTotal = counts[5] + counts[6];
    if (refs.weekdayNote) {
      refs.weekdayNote.textContent = single
        ? "single day"
        : "Mon–Fri " + groupDigits(weekdayTotal) + " · Sat–Sun " + groupDigits(weekendTotal);
      refs.weekdayNote.classList.add("is-accent");
    }

    var max = Math.max.apply(null, counts);
    if (!max) max = 1;

    var pad = 10;
    var gap = 8;
    var slot = (width - pad * 2 - gap * 6) / 7;
    var baseline = height - 26;
    var chartHeight = baseline - 34;

    /* weekday markers for the start and end dates */
    var startIndex = weekdayIndex(fromDays);
    var endIndex = weekdayIndex(toDays);

    for (var index = 0; index < 7; index += 1) {
      var x = pad + index * (slot + gap);
      var barHeight = Math.max(counts[index] > 0 ? 3 : 0, (counts[index] / max) * chartHeight);
      var weekend = index >= 5;
      ctx.fillStyle = weekend ? "rgba(240,234,221,0.2)" : c.accent;
      if (weekend) ctx.globalAlpha = 1;
      ctx.fillRect(x, baseline - barHeight, slot, barHeight);

      ctx.fillStyle = c.bone3;
      ctx.font = "10px " + monoStack();
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      ctx.fillText(WEEKDAY_LETTERS[index], x + slot / 2, baseline + 8);

      if (counts[index]) {
        ctx.fillStyle = c.bone2;
        ctx.textBaseline = "bottom";
        ctx.fillText(String(counts[index]), x + slot / 2, baseline - barHeight - 4);
      }

      if (index === startIndex) {
        ctx.fillStyle = c.accent;
        ctx.beginPath();
        ctx.arc(x + slot / 2, baseline - barHeight - 16, 3.5, 0, Math.PI * 2);
        ctx.fill();
      }
      if (index === endIndex) {
        var markerY = index === startIndex ? baseline - barHeight - 26 : baseline - barHeight - 16;
        ctx.strokeStyle = c.bone;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(x + slot / 2, markerY, 3.5, 0, Math.PI * 2);
        ctx.stroke();
      }
    }

    ctx.strokeStyle = c.rule;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(pad, baseline + 0.5);
    ctx.lineTo(width - pad, baseline + 0.5);
    ctx.stroke();

    ctx.fillStyle = c.bone3;
    ctx.font = "10px " + monoStack();
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(WEEKDAY_SHORT[startIndex] + " " + fromIso, pad, baseline + 24);
    ctx.textAlign = "right";
    ctx.fillText(WEEKDAY_SHORT[endIndex] + " " + toIso, width - pad, baseline + 24);
  }

  function drawAll(fromIso, toIso) {
    colourCache = null;
    drawSpan(fromIso, toIso);
    drawWeekdays(fromIso, toIso);
  }

  /* ====================================================================== */
  /* 5. Request cycle                                                        */
  /* ====================================================================== */
  function payloadFor(inputs) {
    if (inputs.mode === "shift") {
      return {
        operation: inputs.direction === "subtract" ? "subtract" : "add",
        date: inputs.date,
        amount: inputs.amount === "" ? 0 : inputs.amount,
        unit: inputs.unit,
        business_days: inputs.business === true
      };
    }
