  }

  function paint(result, inputs, options) {
    var opts = options || {};
    var primary = primaryReadout(result, inputs);

    if (refs.dayCount) {
      refs.dayCount.classList.remove("is-error", "is-accent");
      refs.dayCount.textContent = primary.value;
      if (primary.error) refs.dayCount.classList.add("is-error");
      else refs.dayCount.classList.add("is-accent");
    }
    if (refs.dayUnit) {
      refs.dayUnit.textContent = primary.unit;
      if (primary.error) refs.dayUnit.classList.add("is-hidden");
      else refs.dayUnit.classList.remove("is-hidden");
    }
    if (refs.caption) refs.caption.textContent = primary.caption;

    if (opts.source === "api" && result && result.ok) setBadge("verified", "api");
    else if (result && !result.ok) setBadge("error", "error");
    else setBadge("live", "local");

    renderBreakdown(result);

    var fromIso = result && result.ok ? result.start : inputs.mode === "shift" ? inputs.date : inputs.start;
    var toIso = result && result.ok ? endIsoOf(result) : inputs.mode === "shift" ? inputs.date : inputs.end;
    state.fromIso = parseISO(fromIso) ? fromIso : "";
    state.toIso = parseISO(toIso) ? toIso : "";
