  }

  function askServer(inputs) {
    var payload = payloadFor(inputs);
    var sequence = state.sequence + 1;
    state.sequence = sequence;
    var url = (shell && shell.meta && shell.meta.api) || "/api/date";

    var request =
      shell && typeof shell.fetchJSON === "function"
        ? shell.fetchJSON(url, payload)
        : fetch(url, {
            method: "POST",
            headers: { "Content-Type": "application/json", Accept: "application/json" },
            body: JSON.stringify(payload)
          }).then(function (response) {
            return response.json().then(function (data) {
              return { ok: response.ok, status: response.status, data: data };
            });
          });

    request
      .then(function (response) {
        if (sequence !== state.sequence) return;
        var data = response && response.data;
        if (response && response.ok && data && typeof data.ok === "boolean") {
          state.result = data;
          paint(data, inputs, { source: "api" });
          return;
        }
        var local = calculateLocal(inputs);
        state.result = local;
        paint(local, inputs, { source: "local" });
        if (refs.engineChip) refs.engineChip.textContent = "local fallback";
      })
      .catch(function () {
        if (sequence !== state.sequence) return;
        var local = calculateLocal(inputs);
        state.result = local;
        paint(local, inputs, { source: "local" });
        if (refs.engineChip) refs.engineChip.textContent = "local fallback";
      });
