  }

  function labelFor(inputs, result) {
    if (inputs.mode === "shift") {
      return inputs.date + " " + (inputs.direction === "subtract" ? "−" : "+") + " " + inputs.amount + " " + inputs.unit +
        (inputs.business ? " (business)" : "");
