      ? groupDigits(result.total_days) + " days"
      : result.result;
    pushHistory({
      mode: inputs.mode,
      label: labelFor(inputs, result),
      value: value,
      inputs: {
        mode: inputs.mode,
        start: inputs.start,
        end: inputs.end,
        date: inputs.date,
        amount: inputs.amount,
        unit: inputs.unit,
        direction: inputs.direction,
        business: inputs.business
