  /* ====================================================================== */
  /* 6. Wiring                                                               */
  /* ====================================================================== */
  function setMode(mode, options) {
    var next = mode === "shift" ? "shift" : "difference";
    var changed = next !== state.mode;
    state.mode = next;
    for (var i = 0; i < refs.subtabs.length; i += 1) {
      var tab = refs.subtabs[i];
