  }

  function handlePreset(name, scope) {
    var today = todayIso();
    if (scope === "shift") {
      if (refs.date && !refs.date.value) refs.date.value = today;
      var base = refs.date && refs.date.value ? refs.date.value : today;
      if (name === "today") {
        if (refs.date) refs.date.value = today;
        if (refs.amount) refs.amount.value = "0";
      } else if (name === "plus30") {
        if (refs.amount) refs.amount.value = "30";
        if (refs.unit) refs.unit.value = "days";
