        if (index === -1) return;
        var next = -1;
        if (event.key === "ArrowRight" || event.key === "ArrowDown") next = (index + 1) % tabs.length;
        else if (event.key === "ArrowLeft" || event.key === "ArrowUp") next = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === "Home") next = 0;
        else if (event.key === "End") next = tabs.length - 1;
        else return;
        event.preventDefault();
        tabs[next].focus();
        setMode(tabs[next].getAttribute("data-subtab"));
      });
    }

    [refs.start, refs.end, refs.date, refs.amount, refs.unit].forEach(function (input) {
      if (!input) return;
      input.addEventListener("input", function () {
        refresh();
      });
      input.addEventListener("change", function () {
        refresh();
      });
    });

    for (var i = 0; i < refs.directionButtons.length; i += 1) {
      refs.directionButtons[i].addEventListener("click", function (event) {
        setDirection(event.currentTarget.getAttribute("data-direction"));
      });
    }

    if (refs.business) {
      refs.business.addEventListener("click", function () {
        setBusiness(!state.business);
      });
    }

    for (var j = 0; j < refs.presets.length; j += 1) {
      refs.presets[j].addEventListener("click", function (event) {
        var button = event.currentTarget;
        var panel = button.closest ? button.closest("[data-subpanel]") : null;
        var scope = panel ? panel.getAttribute("data-subpanel") : state.mode;
        handlePreset(button.getAttribute("data-preset"), scope);
      });
    }

    if (refs.history) {
      refs.history.addEventListener("click", function (event) {
        var button = event.target && event.target.closest ? event.target.closest("[data-index]") : null;
        if (!button) return;
        var entry = state.history[Number(button.getAttribute("data-index"))];
        if (!entry || !entry.inputs) return;
        var inputs = entry.inputs;
        setMode(inputs.mode || "difference", { quiet: true });
        setInputValues(inputs);
        refresh();
        announce("Restored " + entry.label);
      });
    }

    if (refs.historyClear) {
      refs.historyClear.addEventListener("click", function () {
        state.history = [];
        saveHistory();
        renderHistory();
        announce("Recent answers cleared");
      });
    }

