    /* Snapshot the answer into history when the user leaves the field, which
       is the natural "I'm done with this one" moment. */
    [refs.start, refs.end, refs.date, refs.amount].forEach(function (input) {
      if (!input) return;
      input.addEventListener("blur", function () {
        var inputs = readInputs();
        remember(inputs, state.result || calculateLocal(inputs));
      });
    });
  }

  function defaults() {
    var today = todayIso();
    var todayDays = dayNumberOf(parseISO(today));
    if (refs.start && !refs.start.value) refs.start.value = isoFromDayNumber(todayDays - 30);
    if (refs.end && !refs.end.value) refs.end.value = today;
    if (refs.date && !refs.date.value) refs.date.value = today;
    if (refs.amount && !refs.amount.value) refs.amount.value = "30";
    if (refs.unit && !refs.unit.value) refs.unit.value = "days";
    setDirection(state.direction, true);
    setBusiness(state.business, true);
  }

  ready(function () {
    collect();
    state.history = loadHistory();
    renderHistory();
    defaults();
    wire();
    setMode("difference", { quiet: true });
    remember(readInputs(), state.result);
  });

  /* Exposed for the standalone preview / console debugging. */
  window.NumeraDate = {
    difference: difference,
    shift: shift,
    calculateLocal: calculateLocal,
    parseISO: parseISO,
    displayOfIso: displayOfIso,
    weekdayIndex: weekdayIndex,
    ymdBetween: ymdBetween,
    state: state
  };
})();

