cd . && cat > /tmp/verify/harness_date.js <<'EOF'
const fs = require('fs');
const vm = require('vm');
const sandbox = {};
sandbox.window = sandbox;
sandbox.globalThis = sandbox;
sandbox.console = console;
sandbox.setTimeout = setTimeout;
sandbox.clearTimeout = clearTimeout;
sandbox.Date = Date;
sandbox.Math = Math;
sandbox.JSON = JSON;
sandbox.localStorage = { getItem() { return null; }, setItem() {} };
sandbox.matchMedia = () => ({ matches: false, addEventListener() {} });
sandbox.getComputedStyle = () => ({ getPropertyValue: () => '' });
sandbox.document = {
  readyState: 'loading',
  addEventListener() {},
  querySelector() { return null; },
  querySelectorAll() { return []; },
  body: {},
  createElement() { return { className: '', textContent: '', appendChild() {}, setAttribute() {}, classList: { add() {}, remove() {}, toggle() {} }, style: {} }; }
};
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync(process.argv[2], 'utf8'), sandbox, { filename: 'date.js' });
const api = sandbox.NumeraDate;
const cases = JSON.parse(fs.readFileSync(process.argv[3], 'utf8'));
const out = cases.map((c) => {
  if (c.kind === 'difference') return api.difference(c.start, c.end);
  return api.shift(c.kind, c.date, String(c.amount), c.unit, c.business);
});
fs.writeFileSync(process.argv[4], JSON.stringify(out, null, 1));
console.log('cases', out.length, 'ok', out.filter(o => o.ok).length);
EOF
cat > /tmp/verify/parity_dates.py <<'EOF'
import json, random, subprocess, sys
sys.path.insert(0, '.')
from calculators import dates as D

random.seed(3)
cases = []
dates = ["2024-01-01", "2024-01-31", "2024-02-29", "2023-02-28", "2025-12-31",
         "1999-12-31", "2000-02-29", "1900-03-01", "2024-03-01", "2024-12-31",
         "1970-01-01", "2038-01-19", "2021-01-01", "2024-06-15", "2026-10-27"]
for a in dates:
    for b in dates:
        cases.append({"kind": "difference", "start": a, "end": b})
for i in range(80):
    a = random.choice(dates)
    b = "%04d-%02d-%02d" % (random.randint(1900, 2100), random.randint(1, 12), random.randint(1, 28))
    cases.append({"kind": "difference", "start": a, "end": b})
units = ["days", "weeks", "months", "years"]
amounts = [0, 1, 2, 5, 7, 30, 365, -1, -30, -365, 12, 100]
for d in dates:
    for u in units:
        for amt in amounts:
            for kind in ("add", "subtract"):
                if abs(amt) > 365 and u in ("months", "years"):
                    continue
                cases.append({"kind": kind, "date": d, "amount": amt, "unit": u})
for d in ["2024-01-31", "2024-02-29", "2024-03-02", "2024-03-03", "2025-12-31", "2024-01-06"]:
    for amt in [0, 1, 2, 3, 4, 5, 10, 21, -1, -3, -10]:
        for kind in ("add", "subtract"):
            cases.append({"kind": kind, "date": d, "amount": amt, "unit": "days", "business": True})
# invalid
for bad in [{"kind": "difference", "start": "", "end": "2024-01-01"},
            {"kind": "difference", "start": "2024-02-30", "end": "2024-01-01"},
            {"kind": "add", "date": "2024-01-01", "amount": "x", "unit": "days"},
            {"kind": "add", "date": "2024-01-01", "amount": 1, "unit": "months", "business": True},
            {"kind": "subtract", "date": "2024-01-01", "amount": 1, "unit": "centuries"}]:
    cases.append(bad)

json.dump(cases, open('/tmp/verify/datecases.json', 'w'))
proc = subprocess.run(['/tmp/jsrt/nodejs/bin/node', '/tmp/verify/harness_date.js',
                       'static/js/date.js', '/tmp/verify/datecases.json',
                       '/tmp/verify/dateout.json'], capture_output=True, text=True)
print(proc.stdout.strip(), proc.stderr.strip()[:1500])
out = json.load(open('/tmp/verify/dateout.json'))

FIELDS_DIFF = ["total_days", "years", "months", "days", "display", "weekdays", "weekend_days",
               "weeks", "days_remainder", "sign", "direction", "start", "end",
               "start_display", "end_display", "signed_days"]
FIELDS_SHIFT = ["start", "result", "start_display", "result_display", "amount", "signed_amount",
                "unit", "business_days", "days_moved", "direction", "clamped", "note",
                "day_of_year", "leap_year", "iso_week"]
bad = 0
for case, js in zip(cases, out):
    if case["kind"] == "difference":
        py = D.difference(case["start"], case["end"]) if case["start"] and case["end"] else None
        try:
            py = D.difference(case["start"], case["end"])
        except Exception as exc:
            py = {"ok": False, "error": str(exc)}
        fields = FIELDS_DIFF
    else:
        try:
            py = D.add(case["date"], case["amount"], case["unit"], case.get("business", False)) if case["kind"] == "add" \
                 else D.subtract(case["date"], case["amount"], case["unit"], case.get("business", False))
        except D.DateError as exc:
            py = {"ok": False, "error": str(exc)}
        except Exception as exc:
            py = {"ok": False, "error": str(exc)}
        fields = FIELDS_SHIFT
    if py.get("ok") != js.get("ok"):
        bad += 1
        print("OK-DIFF", case, py.get("ok"), js.get("ok"), "|", py.get("error"), "|", js.get("error"))
        continue
    if not py.get("ok"):
        continue
    for f in fields:
        if py.get(f) != js.get(f):
            bad += 1
            print("FIELD", f, case, repr(py.get(f)), repr(js.get(f)))
print("checked", len(cases), "problems", bad)
EOF
