{% extends "base.html" %}

{#-
  Graphing mode — the plot bench.
  ===============================
  DOM order is plot first, editor second, so a phone lands on the picture; above
  980px the grid puts the editor in column 1 and the plot in column 2 (Desmos
  habit: type on the left, watch on the right).

  Who owns what
    this file        markup + the graph-scoped styles in {% block styles %}
    static/js/graph.js  every behaviour: expression mirror (same syntax as
                        calculators/engine.py), local sampling for pan/zoom,
                        canvas painting, hover crosshair, legend, /api/graph
                        seeding + validation.
    app.py           GRAPH_DEFAULTS -> `graph` context -> rows below + the JSON
                     block at the bottom, so the first paint is server-seeded.

  Hooks queried by graph.js
    [data-curves] [data-curve] [data-curve-colour] [data-curve-expression]
    [data-curve-visible] [data-curve-remove] [data-curve-error] [data-curve-meta]
    [data-add-curve] [data-curve-count] [data-angle] [data-x-min] [data-x-max]
    [data-y-min] [data-y-max] [data-auto-y] [data-preset-min] [data-preset-max]
    [data-plot-canvas] [data-plot-shell] [data-plot-tip] [data-plot-status]
    [data-plot-summary] [data-legend] [data-graph-alert] [data-engine-chip]
    [data-zoom] [data-reset] [data-curve-max]
-#}

{%- set g = graph | default({
      'expressions': ['sin(x)', '0.2*x^2 - 3'],
      'colours': ['#f2b457', '#7fd4c1'],
      'palette': ['#f2b457', '#7fd4c1', '#b79bf6', '#f2818f', '#8fb7ff', '#d9e08a', '#f0a2d0', '#e6c07a'],
      'x_min': -10,
      'x_max': 10,
      'angle_mode': 'deg',
      'samples': 400,
      'max_curves': 8,
      'presets': [
        {'label': '−10 … 10', 'x_min': -10, 'x_max': 10},
        {'label': '−2π … 2π', 'x_min': -6.28318530718, 'x_max': 6.28318530718},
        {'label': '−360 … 360', 'x_min': -360, 'x_max': 360},
        {'label': '−1 … 1', 'x_min': -1, 'x_max': 1},
        {'label': '0 … 100', 'x_min': 0, 'x_max': 100}
      ]
    }) -%}

{% block title %}Graphing · Numera{% endblock %}

{% block styles %}
<style>
/* --------------------------------------------------------------------------
   Graphing panel — every rule here is scoped to this mode's markup (.graph-*,
   .curve*) and reads its colour from the mode tokens in style.css, so the whole
   bench repaints from body[data-mode].  Kept in this template so the panel is
   self-contained: copying the <style> block with the markup is enough.
   -------------------------------------------------------------------------- */

/* ---- bench grid: plot first in the DOM, editor on the left when wide ----- */
.graph-bench {
  display: grid;
  gap: var(--gap);
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
}

@media (min-width: 980px) {
  .graph-bench {
    grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.18fr);
  }

  .graph-plot {
    grid-column: 2;
    grid-row: 1;
  }

  .graph-editor {
    grid-column: 1;
    grid-row: 1;
  }
}

/* ---- plot frame --------------------------------------------------------- */
.graph-plot {
  display: grid;
  gap: 0.55rem;
  margin: 0;
  min-width: 0;
}

.graph-plot__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem 0.9rem;
  flex-wrap: wrap;
}

.graph-plot__status {
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.04em;
  color: var(--bone-2);
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.graph-plot__status b {
  font-weight: 600;
  color: var(--accent);
}

.graph-toolbar {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  flex-wrap: wrap;
}

.graph-toolbar .btn {
  padding: 0.28rem 0.55rem;
  font-size: var(--fs-micro);
  letter-spacing: 0.03em;
}

.graph-toolbar__sep {
  width: 1px;
  height: 1.15rem;
  margin-inline: 0.15rem;
  background: var(--rule-soft);
}

/* Auto-y switch: a small physical toggle, not a checkbox row. */
.graph-switch {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.2rem 0.52rem 0.2rem 0.34rem;
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.06em;
  color: var(--bone-2);
  cursor: pointer;
  transition: border-color var(--dur-fast) var(--ease),
    background-color var(--dur-fast) var(--ease);
}

.graph-switch:hover {
  border-color: var(--rule-strong);
}

.graph-switch input {
  appearance: none;
  -webkit-appearance: none;
  position: relative;
  flex: 0 0 auto;
  width: 1.7rem;
  height: 0.92rem;
  margin: 0;
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  background: rgba(0, 0, 0, 0.45);
  cursor: pointer;
  transition: background-color var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease);
}

.graph-switch input::after {
  content: "";
  position: absolute;
  top: 1px;
  left: 1px;
  width: calc(0.92rem - 4px);
  height: calc(0.92rem - 4px);
  border-radius: 50%;
  background: var(--bone-3);
  transition: transform var(--dur-fast) var(--ease),
    background-color var(--dur-fast) var(--ease);
}

.graph-switch input:checked {
  background: var(--accent-soft);
  border-color: var(--accent-line);
}

.graph-switch input:checked::after {
  transform: translateX(0.78rem);
  background: var(--accent);
}

.graph-switch input:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.graph-switch:has(input:checked) {
  border-color: var(--accent-line);
  color: var(--bone);
}

/* ---- the canvas shell --------------------------------------------------- */
.graph-canvas-shell {
  position: relative;
  height: clamp(280px, 42vh, 500px);
  touch-action: none;
  cursor: crosshair;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.34), rgba(0, 0, 0, 0.16));
}

.graph-canvas-shell canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

.graph-canvas-shell.is-dragging {
  cursor: grabbing;
}

.graph-canvas-shell canvas:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--r-md);
}

/* Hover readout card: floats near the crosshair, pointer-events none. */
.graph-tip {
  position: absolute;
  top: 0.45rem;
  left: 0;
  display: grid;
  gap: 0.12rem;
  min-width: 8.25rem;
  max-width: 12.5rem;
  padding: 0.34rem 0.45rem 0.4rem;
  border: 1px solid var(--accent-line);
  border-radius: var(--r-sm);
  background: rgba(6, 10, 10, 0.94);
  box-shadow: 0 12px 26px -20px #000, var(--lift);
  pointer-events: none;
}

.graph-tip[hidden] {
  display: none;
}

.graph-tip__x {
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.05em;
  font-variant-numeric: tabular-nums;
  color: var(--accent);
}

.graph-tip__row {
  display: flex;
  align-items: baseline;
  gap: 0.32rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  color: var(--bone-2);
  min-width: 0;
}

.graph-tip__expr {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.graph-tip__y {
  margin-left: auto;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}

.graph-tip__y.is-undefined {
  color: var(--bone-3);
}

@media (max-width: 620px) {
  .graph-tip {
    display: none;
  }
}

.graph-plot__hint {
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.03em;
  line-height: 1.55;
  color: var(--bone-3);
}

/* ---- legend (doubles as the live readout column) ------------------------ */
.graph-legend {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 1px;
  border-top: 1px solid var(--rule-soft);
}

.graph-legend li {
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  min-width: 0;
  padding: 0.32rem 0.1rem;
  border-bottom: 1px solid var(--rule-soft);
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
  font-variant-numeric: tabular-nums;
}

.graph-legend li.is-hidden {
  opacity: 0.45;
}

.graph-legend__swatch,
.graph-tip__swatch {
  flex: 0 0 auto;
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 1px;
  background: var(--swatch, var(--accent));
}

.graph-legend__expr {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--bone-2);
}

.graph-legend__value {
  margin-left: auto;
  color: var(--bone);
}

.graph-legend__value.is-undefined {
  color: var(--bone-3);
}

.graph-legend__empty {
  padding: 0.5rem 0.1rem;
  font-size: var(--fs-sm);
  color: var(--bone-3);
}

/* ---- alert strip -------------------------------------------------------- */
.graph-alert {
  margin: 0;
  padding: 0.42rem 0.6rem;
  border: 1px solid rgba(255, 154, 140, 0.34);
  border-radius: var(--r-sm);
  background: rgba(255, 154, 140, 0.08);
  color: var(--danger);
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.02em;
  line-height: 1.5;
}

.graph-alert[hidden] {
  display: none;
}

/* ---- curve rows --------------------------------------------------------- */
.curves {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.5rem;
}

.curve {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  gap: 0.3rem;
  align-items: center;
}

.curve__swatch {
  appearance: none;
  -webkit-appearance: none;
  width: 1.5rem;
  height: 1.5rem;
  padding: 0;
  border: 1px solid var(--rule);
  border-radius: var(--r-xs);
  background: transparent;
  cursor: pointer;
}

.curve__swatch::-webkit-color-swatch-wrapper {
  padding: 2px;
}

.curve__swatch::-webkit-color-swatch {
  border: 0;
  border-radius: 1px;
}

.curve__swatch::-moz-color-swatch {
  border: 0;
  border-radius: 1px;
}

.curve__swatch:hover {
  border-color: var(--rule-strong);
}

.curve__swatch:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.curve__input {
  font-size: 0.9375rem;
  padding: 0.42rem 0.55rem;
  min-width: 0;
}

.curve__input[aria-invalid="true"] {
  border-color: var(--danger);
  background: rgba(255, 154, 140, 0.06);
}

.curve__eye,
.curve__remove {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.55rem;
  height: 1.55rem;
  padding: 0;
  border: 1px solid var(--rule-soft);
  border-radius: var(--r-xs);
  background: var(--tone-raise);
  color: var(--bone-3);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  line-height: 1;
  cursor: pointer;
  transition: color var(--dur-fast) var(--ease),
    border-color var(--dur-fast) var(--ease),
    background-color var(--dur-fast) var(--ease);
}

.curve__eye::before {
  content: "◉";
}

.curve__eye[aria-pressed="false"]::before {
  content: "◌";
}

.curve__eye[aria-pressed="true"] {
  color: var(--accent);
  border-color: var(--accent-line);
}

.curve__eye:hover,
.curve__remove:hover {
  color: var(--bone);
  background: var(--tone-key-hover);
}

.curve__remove:hover {
  color: var(--danger);
  border-color: rgba(255, 154, 140, 0.4);
}

.curve__eye:focus-visible,
.curve__remove:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Inline validation message + sampling meta live under the field. */
.curve__error {
  grid-column: 2 / -1;
  margin: -0.1rem 0 0;
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.02em;
  line-height: 1.45;
  color: var(--danger);
  overflow-wrap: anywhere;
}

.curve__error[hidden] {
  display: none;
}

.curve__meta {
  grid-column: 2 / -1;
  margin: -0.1rem 0 0;
  font-family: var(--font-mono);
  font-size: var(--fs-micro);
  letter-spacing: 0.02em;
  color: var(--bone-3);
  font-variant-numeric: tabular-nums;
}

.curve__meta:empty {
  display: none;
}

/* ---- view controls ------------------------------------------------------ */
.graph-presets {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.graph-presets .btn[aria-pressed="true"] {
  border-color: var(--accent-line);
  background: var(--accent-soft);
  color: var(--accent);
}

.graph-editor .presets__label {
  margin-right: 0.1rem;
}

/* Narrow phones: the row keeps all four controls, the field just gets smaller. */
@media (max-width: 420px) {
  .curve {
    gap: 0.22rem;
  }

  .curve__swatch {
    width: 1.35rem;
    height: 1.35rem;
  }

  .curve__eye,
  .curve__remove {
    width: 1.4rem;
    height: 1.4rem;
  }

  .graph-canvas-shell {
    height: clamp(240px, 52vh, 380px);
  }
}

@media (prefers-contrast: more) {
  .graph-plot__status,
  .graph-plot__hint,
  .curve__meta {
    color: var(--bone-2);
  }

  .graph-legend__expr {
    color: var(--bone);
  }
}

@media print {
  .graph-toolbar {
    display: none;
  }
}
</style>
{% endblock %}

{% block content %}
<section class="panel graph" aria-labelledby="graph-title" data-graph
         data-max-curves="{{ g.max_curves | default(8) }}"
         data-default-x-min="{{ '%g' | format(g.x_min) }}"
         data-default-x-max="{{ '%g' | format(g.x_max) }}">

  <header class="panel__head">
    <h2 class="panel__title" id="graph-title">Plot bench</h2>
    <div class="row">
      <div class="seg" role="group" aria-label="Angle unit">
        <button type="button" class="seg__btn" data-angle="deg"
                aria-pressed="{{ 'true' if g.angle_mode != 'rad' else 'false' }}"
                title="Degrees — sin(90) = 1">DEG</button>
        <button type="button" class="seg__btn" data-angle="rad"
                aria-pressed="{{ 'true' if g.angle_mode == 'rad' else 'false' }}"
                title="Radians — sin(pi/2) = 1">RAD</button>
      </div>
      <span class="chip chip--accent">Graphing mode</span>
      <span class="chip" data-engine-chip>local engine</span>
    </div>
  </header>

  <div class="graph-bench">

    {# ------------------------------ the plot ---------------------------- #}
    <figure class="graph-plot" aria-labelledby="graph-plot-title">

      <figcaption class="graph-plot__head">
        <span class="viz__title" id="graph-plot-title">Plot</span>
        <span class="graph-plot__status" data-plot-status
              aria-live="polite">x ∈ [−10, 10] · y auto · 2 curves</span>
      </figcaption>

      <div class="graph-toolbar" role="group" aria-label="Plot navigation">
        <button type="button" class="btn" data-zoom="in" title="Zoom in">Zoom in</button>
        <button type="button" class="btn" data-zoom="out" title="Zoom out">Zoom out</button>
        <button type="button" class="btn" data-reset title="Back to the default window">Reset</button>
        <span class="graph-toolbar__sep" aria-hidden="true"></span>
        <label class="graph-switch" title="Fit the y axis to the curves">
          <input type="checkbox" data-auto-y checked>
          <span>Auto y</span>
        </label>
        <span class="graph-toolbar__sep" aria-hidden="true"></span>
        <div class="graph-presets" role="group" aria-label="Preset x ranges">
          {%- for preset in g.presets %}
          <button type="button" class="btn"
                  data-preset-min="{{ preset.x_min }}" data-preset-max="{{ preset.x_max }}"
                  aria-pressed="false">{{ preset.label }}</button>
          {%- endfor %}
        </div>
      </div>

      <div class="plot graph-canvas-shell" data-plot-shell>
        <canvas data-plot-canvas tabindex="0" role="img"
                aria-label="Plot of the curves in the list, drawn on a grid with labelled axes."
                aria-describedby="graph-plot-help"></canvas>
        <div class="graph-tip" data-plot-tip hidden aria-hidden="true"></div>
      </div>

      <p class="graph-plot__hint" id="graph-plot-help">
        Drag to pan · wheel or pinch to zoom · <kbd>←</kbd> <kbd>→</kbd> nudge ·
        <kbd>↑</kbd> <kbd>↓</kbd> zoom · <kbd>0</kbd> resets. Gaps mark undefined
        points, so asymptotes break instead of jumping.
      </p>

      <ul class="graph-legend" data-legend aria-label="Curves"></ul>

      <p class="graph-alert" data-graph-alert role="status" hidden></p>

      <p class="sr-only" data-plot-summary></p>
    </figure>

    {# ----------------------------- the editor --------------------------- #}
    <div class="graph-editor stack">

      <section class="stack stack--tight" aria-labelledby="graph-curves-title">
        <div class="row">
          <h3 class="label" id="graph-curves-title" style="margin-bottom:0">Curves</h3>
          <span class="meta" data-curve-count>{{ g.expressions | length }} / {{ g.max_curves | default(8) }}</span>
          <span class="row" style="margin-left:auto">
            <button type="button" class="btn btn--small" data-add-curve
                    data-curve-max="{{ g.max_curves | default(8) }}">+ Add curve</button>
          </span>
        </div>

        <ol class="curves" data-curves>
          {%- for expression in g.expressions %}
          {%- set colour = g.colours[loop.index0] if loop.index0 < (g.colours | length) else g.palette[loop.index0 % (g.palette | length)] %}
          <li class="curve" data-curve data-curve-colour-value="{{ colour }}">
            <input class="curve__swatch" type="color" value="{{ colour }}" data-curve-colour
                   aria-label="Colour for curve {{ loop.index }}" title="Curve colour">
            <input class="input curve__input" type="text" value="{{ expression }}"
                   data-curve-expression spellcheck="false" autocapitalize="off"
                   autocorrect="off" autocomplete="off" inputmode="text"
                   placeholder="sin(x)" aria-label="Expression for curve {{ loop.index }}"
                   aria-describedby="curve-error-{{ loop.index }}">
            <button type="button" class="curve__eye" data-curve-visible aria-pressed="true"
                    title="Hide this curve" aria-label="Show or hide curve {{ loop.index }}"></button>
            <button type="button" class="curve__remove" data-curve-remove
                    title="Remove this curve" aria-label="Remove curve {{ loop.index }}">×</button>
            <p class="curve__error" id="curve-error-{{ loop.index }}" data-curve-error hidden></p>
            <p class="curve__meta" data-curve-meta></p>
          </li>
          {%- endfor %}
        </ol>

        <p class="note">
          <span class="meta">x</span> is the variable. Functions, constants and
          operators match the scientific mode: <span class="meta">sqrt(x)</span>,
          <span class="meta">ln(x)</span>, <span class="meta">tan(x)</span>,
          <span class="meta">pi</span>. Rows turn amber-checked against the Python
          engine as you type.
        </p>
      </section>

      <section class="stack stack--tight" aria-labelledby="graph-view-title">
        <h3 class="label" id="graph-view-title">View</h3>

        <div class="pair">
          <div class="field">
            <label class="label" for="graph-x-min">x min</label>
            <input class="input" id="graph-x-min" type="number" step="any" inputmode="decimal"
                   data-x-min value="{{ '%g' | format(g.x_min) }}">
          </div>
          <div class="field">
            <label class="label" for="graph-x-max">x max</label>
            <input class="input" id="graph-x-max" type="number" step="any" inputmode="decimal"
                   data-x-max value="{{ '%g' | format(g.x_max) }}">
          </div>
        </div>

        <div class="pair">
          <div class="field">
            <label class="label" for="graph-y-min">y min</label>
            <input class="input" id="graph-y-min" type="number" step="any" inputmode="decimal"
                   data-y-min disabled>
          </div>
          <div class="field">
            <label class="label" for="graph-y-max">y max</label>
            <input class="input" id="graph-y-max" type="number" step="any" inputmode="decimal"
                   data-y-max disabled>
          </div>
        </div>

        <div class="graph-presets" role="group" aria-label="Preset x ranges">
          <span class="presets__label">Ranges</span>
          {%- for preset in g.presets %}
          <button type="button" class="btn btn--small"
                  data-preset-min="{{ preset.x_min }}" data-preset-max="{{ preset.x_max }}"
                  aria-pressed="false">{{ preset.label }}</button>
          {%- endfor %}
        </div>

        <p class="note">
          Panning and zooming sample in the browser so the drag stays smooth;
          the server engine checks the same expressions and seeds the first frame.
        </p>
      </section>

      <noscript>
        <p class="note">
          The canvas plot needs JavaScript. The expressions above are still sent to
          <span class="meta">/api/graph</span> and validated by the Python engine.
        </p>
      </noscript>
    </div>
  </div>
</section>

{#- Server-seeded defaults: rows above are rendered from this same dict. -#}
<script type="application/json" id="graph-defaults">{{ g | tojson }}</script>
{% endblock %}

{% block scripts %}
<script src="{{ url_for('static', filename='js/graph.js') }}" defer></script>
{% endblock %}
